window.TADABBUR_MARYAM = {"_meta":{"description":"تدبّرٌ مُسنَد لسورة مريم (١٩)، سورةٌ مكّيّةٌ تُفتتَح بـ«كهيعص»، فيها أخبارُ الأنبياء: زكريا ويحيى، ومريمُ وعيسى، وإبراهيمُ وأبوه، وموسى وهارون، وإسماعيلُ وإدريس؛ محورُها إثباتُ رحمةِ الله وتنزيهُه عن الولد. بُدئت بالحمد. كلُّ آيةٍ مغطّاةٍ تحمل وقفةً مُسنَدةً موسومة (ابن كثير/السعدي).","honesty":"لا نُقدّم شيئًا كإعجازٍ مُثبَت؛ المعنى منقولٌ بتصرّفٍ يسير من التفسيرين بإحالةٍ صريحة، ونصُّ الآيةِ لا يُكتَب هاهنا بأيدينا، بل يُنقَل عند القراءةِ من مصحفٍ محقَّقٍ مضبوط، صيانةً له من الخطأ."},"n":19,"name":"مريم","total_ayahs":98,"audio":[1,4,16,33,36,58,71,85,93,96],"passages":[{"title":"مطلعُ السورةِ وذكرُ رحمةِ الله لزكريا","range":[1,6],"theme":"الحروفُ المقطّعة، ونداءُ زكريا الخفيُّ ربَّه أن يهبه وليًّا","verses":[{"n":1,"reflection":{"text":"«كهيعص» — هذه حروفٌ مقطّعةٌ من الحروفِ التي افتُتِحت بها بعضُ السور، الله أعلمُ بمرادِه بها، وفيها إشارةٌ إلى إعجازِ القرآنِ المؤلَّفِ من جنسِ حروفِ العربِ التي عجزوا عن معارضته؛ ففي هذا التسليمُ لله في المتشابهِ وردُّ علمِه إليه؛ فسلّم لله فيما استأثر بعلمه، ولا تتكلّف تأويلَ ما لم يُبيَّن لك.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"التسليمُ لله في المتشابه، وردُّ علمِه إليه."},"action":{"text":"سلّم لله فيما استأثر بعلمه من المتشابهِ كالحروفِ المقطّعة، ولا تتكلّف القولَ فيها بلا علم؛ واستحضر إعجازَ القرآنِ الذي عجز العربُ عن معارضته بحروفهم."}},{"n":2,"reflection":{"text":"«ذكر رحمت ربك عبده زكريا» — هذا ذكرُ رحمةِ ربّك لعبده زكريا حين استجاب دعاءه ووهبه الولدَ على الكِبَر؛ ففي هذا أنّ استجابةَ الدعاءِ من رحمةِ الله، وأنّ العبوديةَ الخالصةَ سببٌ لنيلِ الرحمة؛ فتعرّض لرحمةِ الله بالعبوديةِ الصادقة، وارجُها فهي تسع كلَّ محتاج.","source":"تفسير السعدي","grade":"ma'thur"},"names":["رحمت ربك"],"heart_state":{"text":"الرجاءُ في رحمةِ الله، والتعرّضُ لها بالعبودية."},"action":{"text":"تعرّض لرحمةِ الله بصدقِ العبوديةِ والدعاء، وارجُها في كلِّ حاجةٍ مهما تعذّرت الأسباب؛ فرحمتُه وهبت زكريا ولدًا بعد الكِبَرِ والعُقم."}},{"n":3,"reflection":{"text":"«إذ نادى ربه نداء خفيا» — حين دعا زكريا ربَّه دعاءً خفيًّا مسرًّا بعيدًا عن الرياء، أخفى دعاءه ليكون أبلغَ في الإخلاصِ والإجابة؛ ففي هذا فضلُ إخفاءِ الدعاءِ وإسرارِه، وأنه أقربُ للإخلاصِ والقبول؛ فأخفِ دعاءك وتضرّعك، فالدعاءُ الخفيُّ أبعدُ عن الرياءِ وأرجى للإجابة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"إخلاصُ الدعاءِ وإخفاؤه طلبًا للقبول."},"action":{"text":"أسرِر دعاءك وتضرّعك إلى ربّك في خلوةٍ بعيدًا عن الرياء، فالنداءُ الخفيُّ أخلصُ وأرجى للإجابة؛ واجعل بينك وبين ربّك سرًّا من الدعاء."}},{"n":4,"reflection":{"text":"«قال رب إني وهن العظم مني واشتعل الرأس شيبا ولم أكن بدعائك رب شقيا» — قال: ربّ إني ضعُف عظمي وانتشر الشيبُ في رأسي كاشتعالِ النار، ولم أكن بدعائك محرومًا بل عوّدتني الإجابة؛ ففي هذا حسنُ التوسّلِ إلى الله بالضعفِ والافتقار، وبسابقِ إحسانه؛ فتوسّل إلى الله بضعفك وفقرك إليه، وبما عوّدك من إجابته، فذلك أدبُ الدعاء.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"التوسّلُ إلى الله بالضعفِ والافتقارِ وسابقِ إحسانه."},"action":{"text":"توسّل إلى الله في دعائك بإظهارِ ضعفك وحاجتك إليه، واذكر سابقَ إحسانه بك ولطفه؛ فهذا من أبلغِ آدابِ الدعاءِ وأرجاها للإجابة، كما فعل زكريا."}},{"n":5,"reflection":{"text":"«وإني خفت الموالي من ورائي وكانت امرأتي عاقرا فهب لي من لدنك وليا» — وإني خفت أقاربي من بعدي ألّا يقوموا بالدينِ حقَّ القيام، وامرأتي عاقرٌ لا تلد، فهب لي من عندك ولدًا يرثُ العلمَ والنبوّة؛ ففي هذا أنّ الحرصَ على بقاءِ الدينِ في الذريّةِ من همِّ الصالحين، وأنّ العطاءَ من لدنِ الله لا من الأسباب؛ فاحرص على صلاحِ ذريّتك من بعدك، واطلب الولدَ الصالحَ من الله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحرصُ على صلاحِ الذريّةِ وحملِها الدين."},"action":{"text":"اهتمَّ بأن تخلّف من بعدك ذريّةً صالحةً تحمل الدين، وادعُ الله أن يهبك ذلك من عنده؛ فهمُّ زكريا كان بقاءَ الدينِ لا مجردَ الولد، فاجعل ذلك همّك."}},{"n":6,"reflection":{"text":"«يرثني ويرث من آل يعقوب واجعله رب رضيا» — وليًّا يرثني في العلمِ والنبوّة (لا المال، فالأنبياءُ لا يورَّثون)، ويرثُ من آلِ يعقوبَ الدينَ والحكمة، واجعله ربِّ مرضيًّا عندك وعند خلقك في أخلاقه ودينه؛ ففي هذا أنّ خيرَ ما يُطلَب للولدِ أن يكون رضيًّا صالحًا، وأنّ ميراثَ الأنبياءِ العلمُ لا المال؛ فادعُ لولدك أن يكون رضيًّا، واطلب له صلاحَ الدينِ قبل الدنيا.","source":"تفسير السعدي","grade":"ma'thur"},"names":["واجعله رب رضيا"],"heart_state":{"text":"طلبُ الصلاحِ والرضا للذريّةِ قبل كلِّ شيء."},"action":{"text":"ادعُ لأولادك أن يكونوا رضيِّين صالحين مرضيِّين عند الله والناس، واطلب لهم ميراثَ العلمِ والدينِ قبل ميراثِ المال؛ فذلك خيرُ ما يُورَّث."}}]},{"title":"البشارةُ بيحيى وآيةُ الصمت","range":[7,11],"theme":"بشرى الله لزكريا بيحيى، وسؤالُه الآيةَ فكانت ألّا يكلّم الناسَ ثلاثًا","verses":[{"n":7,"reflection":{"text":"«يا زكريا إنا نبشرك بغلام اسمه يحيى لم نجعل له من قبل سميا» — نادى الله زكريا: إنا نبشّرك بغلامٍ اسمه يحيى، لم نسمِّ أحدًا قبله بهذا الاسم، تشريفًا له؛ ففي هذا سرعةُ إجابةِ الله لعبده، وتوليه تسميةَ المولودِ إكرامًا؛ فأبشر بفضلِ الله إذا دعوته، واعلم أنه يكرم أولياءه بما لم يكرم به غيرهم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاستبشارُ بفضلِ الله وسرعةِ إجابته."},"action":{"text":"أحسن الظنَّ بالله وأبشر بإجابته إذا دعوته بصدق، فقد بشّر زكريا بولدٍ مبارَكٍ سمّاه هو سبحانه؛ فادعُ واثقًا بأنّ الله يكرم عبده بما يشاء من فضله."}},{"n":8,"reflection":{"text":"«قال رب أنى يكون لي غلام وكانت امرأتي عاقرا وقد بلغت من الكبر عتيا» — قال زكريا متعجّبًا من قدرةِ الله: ربِّ كيف يكون لي غلامٌ وامرأتي عاقرٌ وقد بلغتُ من الكِبَرِ غايةَ اليُبس؟ ففي هذا أنّ التعجّبَ من عظيمِ قدرةِ الله لا ينافي الإيمان، وأنّ الأسبابَ المعتادةَ قد تنقطع فيأتي فضلُ الله؛ فلا تستبعد فضلَ الله لانقطاعِ الأسباب، فقدرتُه فوق كلِّ سبب.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"عدمُ استبعادِ فضلِ الله عند انقطاعِ الأسباب."},"action":{"text":"لا تستبعد عطاءَ الله وإن انقطعت الأسبابُ المعتادة، فقدرتُه لا يحدّها سبب؛ واطلب منه ما تعذّر على الخلقِ فهو على كلِّ شيءٍ قدير، كما وهب زكريا الولد."}},{"n":9,"reflection":{"text":"«قال كذلك قال ربك هو علي هين وقد خلقتك من قبل ولم تك شيئا» — قال المَلَك: كذلك الأمرُ، قال ربّك: خلقُ الغلامِ عليَّ سهلٌ يسير، وقد خلقتك أنت من قبلُ ولم تكن شيئًا مذكورًا؛ ففي هذا الاستدلالُ على البعثِ والقدرةِ بالخلقِ الأول، وأنّ ما استُصعِب هيّنٌ على الله؛ فاستحضر أنّ خلقك من عدمٍ أعجبُ، فمن أوجدك قادرٌ على كلِّ شيء، فلا تستعظم على قدرته شيئًا.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"استحضارُ يُسرِ كلِّ أمرٍ على الله وقدرتِه المطلقة."},"action":{"text":"استحضر أنّ الله خلقك من عدم، فما تستصعبه من عطائه هيّنٌ عليه؛ فلا تقنط من فضله ولا تستبعد قدرته، فالذي أوجدك من لا شيءٍ يعطيك ما تشاء بأمره «كن»."}},{"n":10,"reflection":{"text":"«قال رب اجعل لي آية قال آيتك ألا تكلم الناس ثلاث ليال سويا» — قال زكريا: ربِّ اجعل لي علامةً أعرف بها حملَ امرأتي فأزداد طمأنينة، قال: علامتُك أن تُمنَع من كلامِ الناسِ ثلاثَ ليالٍ وأنت سليمُ الخلقةِ من غيرِ علّة؛ ففي هذا جوازُ طلبِ العلامةِ للاطمئنان، وأنّ آيتَه كانت حبسَ لسانِه عن الناسِ لا عن ذكرِ الله؛ فاطلب من الله ما يطمئن قلبك، واشغل لسانك بذكرِه إذا مُنِعتَ من غيره.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"طلبُ ما يطمئن القلب، وشغلُ اللسانِ بالذكر."},"action":{"text":"اطلب من الله ما يزيد قلبك طمأنينةً بلا اعتراض، واشغل لسانك بذكرِ الله وتسبيحه؛ فآيةُ زكريا كانت أن يُحبَس لسانه عن الناسِ ويبقى بالتسبيحِ عامرًا."}},{"n":11,"reflection":{"text":"«فخرج على قومه من المحراب فأوحى إليهم أن سبحوا بكرة وعشيا» — فخرج زكريا على قومه من مصلّاه، فأشار إليهم إشارةً خفيّةً أن سبّحوا الله أوّلَ النهارِ وآخرَه؛ ففي هذا أنه لمّا مُنِع الكلامَ دلّهم على التسبيحِ بالإشارة، وفيه فضلُ التسبيحِ طرفي النهار؛ فاعمر طرفي نهارك بتسبيحِ الله وذكره، ودُلَّ الناسَ على الخيرِ بكلِّ وسيلة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["سبحوا بكرة وعشيا"],"heart_state":{"text":"عمارةُ طرفي النهارِ بالتسبيح، والدلالةُ على الخير."},"action":{"text":"اجعل لأوّلِ نهارك وآخِرِه نصيبًا من تسبيحِ الله وذكره، ودُلَّ الناسَ على الخيرِ ولو بالإشارةِ والفعل؛ فزكريا مع منعِ الكلامِ حرص أن يدلَّهم على التسبيح."}}]},{"title":"يحيى: الحكمةُ والحنانُ وبرُّ الوالدين","range":[12,15],"theme":"أوصافُ يحيى: الحكمةُ صبيًّا، والرحمةُ، والتقوى، وبرُّ الوالدين","verses":[{"n":12,"reflection":{"text":"«يا يحيى خذ الكتاب بقوة وآتيناه الحكم صبيا» — يا يحيى خذ التوراةَ بجدٍّ واجتهادٍ وعزيمة، وأعطيناه الفهمَ والعلمَ والحكمةَ وهو صغيرُ السن؛ ففي هذا أنّ أخذَ الكتابِ يكون بقوّةٍ وعزم، وأنّ الله يؤتي الحكمةَ من يشاء ولو صغيرًا؛ فخذ كتابَ ربّك بجدٍّ وعملٍ وعزيمة، ولا تأخذه بتهاونٍ وكسل.","source":"تفسير السعدي","grade":"ma'thur"},"names":["خذ الكتاب بقوة"],"heart_state":{"text":"أخذُ كتابِ الله بجدٍّ وعزيمةٍ وعمل."},"action":{"text":"خذ القرآنَ بقوّةٍ: تعلّمًا جادًّا، وعملًا حازمًا، وعزيمةً لا تفتر؛ ولا تتعامل مع كتابِ ربّك بتهاونٍ أو كسل، فبالجدِّ يُنال العلمُ والحكمة."}},{"n":13,"reflection":{"text":"«وحنانا من لدنا وزكاة وكان تقيا» — وآتيناه رحمةً وشفقةً من عندنا على الخلق، وطهارةً من الذنوب ونماءً في الصلاح، وكان تقيًّا مطيعًا يخشى الله؛ ففي هذا أنّ كمالَ العبدِ في الرحمةِ بالخلقِ والطهارةِ والتقوى؛ فاجمع بين الرحمةِ بالناسِ وطهارةِ القلبِ وتقوى الله، فتلك أوصافُ الصالحين.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الجمعُ بين الرحمةِ بالخلقِ والطهارةِ والتقوى."},"action":{"text":"اجمع في نفسك بين الرحمةِ والشفقةِ بالخلق، وطهارةِ القلبِ من الأدناس، وتقوى الله في السرِّ والعلن؛ فهذه أوصافُ يحيى التي أثنى الله بها عليه."}},{"n":14,"reflection":{"text":"«وبرا بوالديه ولم يكن جبارا عصيا» — وكان بارًّا بوالديه محسنًا إليهما، ولم يكن متكبّرًا عاصيًا لربّه ولا لوالديه؛ ففي هذا قرنُ برِّ الوالدين بطاعةِ الله، وأنّ التواضعَ ضدُّ الجبروتِ والعصيان؛ فبِرَّ والديك وتواضع لهما ولربّك، واحذر الكِبرَ والعقوقَ فهما من صفاتِ الأشقياء.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"برُّ الوالدين والتواضعُ ونبذُ الكِبرِ والعصيان."},"action":{"text":"برَّ والديك وأحسن إليهما وتواضع لهما، واجتنب الكِبرَ والعقوقَ والعصيان؛ فقد أثنى الله على يحيى ببرّه وتواضعه، وهما من أعظمِ ما يُتقرَّب به إلى الله."}},{"n":15,"reflection":{"text":"«وسلام عليه يوم ولد ويوم يموت ويوم يبعث حيا» — وأمانٌ وسلامةٌ من الله على يحيى يومَ ولادته، ويومَ موته، ويومَ يُبعَث حيًّا يومَ القيامة، وهي أشدُّ المواطنِ حاجةً إلى السلامة؛ ففي هذا أنّ العبدَ الصالحَ يُحفَظ في أشدِّ المواطن، وأنّ التقوى تورث السلامةَ في الدنيا والآخرة؛ فاطلب من الله السلامةَ في هذه المواطنِ الثلاثةِ بالتقوى والعمل.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["وسلام عليه"],"heart_state":{"text":"طلبُ السلامةِ من الله في أشدِّ المواطن."},"action":{"text":"اطلب من الله سلامةَ الدينِ والعاقبةِ في أعظمِ مواطنِ الحاجة: عند البعثِ والموتِ والحساب، والزم التقوى التي أورثت يحيى هذا السلام؛ فسلامةُ الآخرةِ غايةُ المطلب."}}]},{"title":"مريمُ وبشارةُ الملكِ بعيسى","range":[16,21],"theme":"اعتزالُ مريمَ، ومجيءُ الروحِ، وبشارتُها بغلامٍ زكيٍّ بقدرةِ الله","verses":[{"n":16,"reflection":{"text":"«واذكر في الكتاب مريم إذ انتبذت من أهلها مكانا شرقيا» — واذكر يا محمد في القرآنِ خبرَ مريمَ حين اعتزلت أهلها وتنحّت إلى مكانٍ شرقيٍّ للعبادةِ والخلوةِ بربّها؛ ففي هذا فضلُ الخلوةِ للعبادةِ والانقطاعِ إلى الله، وأنّ مريمَ كانت من أهلِ العبادة؛ فاتّخذ لنفسك خلواتٍ تنقطع فيها لعبادةِ ربّك بعيدًا عن الشواغل.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"طلبُ الخلوةِ للعبادةِ والانقطاعِ إلى الله."},"action":{"text":"اجعل لك أوقاتَ خلوةٍ تنقطع فيها لعبادةِ ربّك بعيدًا عن الناسِ والشواغل، كما اعتزلت مريمُ للعبادة؛ فالخلوةُ بالله تصفّي القلبَ وتقوّي الصلةَ به."}},{"n":17,"reflection":{"text":"«فاتخذت من دونهم حجابا فأرسلنا إليها روحنا فتمثل لها بشرا سويا» — فجعلت بينها وبين أهلها سترًا يحجبها، فأرسلنا إليها جبريلَ فتصوّر لها في صورةِ إنسانٍ تامِّ الخلقةِ لتأنس ولا تنفر؛ ففي هذا حرصُ مريمَ على السترِ والتحجّب، ولطفُ الله في إرسالِ المَلَكِ بصورةٍ لا تُرهِبها؛ فالزم السترَ والعفاف، واعلم أنّ الله يلطف بعباده في أحوالهم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"لزومُ السترِ والعفاف، وتأمّلُ لطفِ الله."},"action":{"text":"الزم السترَ والحياءَ والعفافَ كما كانت مريمُ تتحجّب عن الناس، وتأمّل لطفَ الله بعباده في تدبيره؛ فالعفّةُ خلقُ الصالحات، ولطفُ الله يحيط بمن أطاعه."}},{"n":18,"reflection":{"text":"«قالت إني أعوذ بالرحمن منك إن كنت تقيا» — قالت مريمُ لمّا رأت الرجلَ في خلوتها: إني أستجير بالرحمنِ منك أن تنالني بسوء، إن كنت تقيًّا تخشى الله فستنتهي بهذه الاستعاذة؛ ففي هذا أنّ الاستعاذةَ بالله ملجأُ العفيفةِ عند الريبة، وأنّ ذكرَ التقوى يردع التقيَّ؛ فالجأ إلى الله عند مواطنِ الريبة، وذكّر الناسَ بتقوى الله لتردعهم عن الشرّ.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الالتجاءُ إلى الله عند الريبة، وتذكيرُ الناسِ بالتقوى."},"action":{"text":"الجأ إلى الله واستعذ به عند كلِّ موطنِ ريبةٍ أو خوف، وذكّر من تخشى شرَّه بتقوى الله؛ فاستعاذةُ مريمَ بالرحمنِ كانت أوّلَ سلاحها في الدفاعِ عن عفّتها."}},{"n":19,"reflection":{"text":"«قال إنما أنا رسول ربك لأهب لك غلاما زكيا» — قال المَلَك: لست بشرًا أخشاه، إنما أنا رسولُ ربّك أرسلني لأكون سببًا في هبةِ غلامٍ طاهرٍ زكيٍّ لك؛ ففي هذا طمأنةُ المَلَكِ لها ببيانِ حقيقته ومهمّته، وأنّ العطاءَ من الله والمَلَكُ سبب؛ فاعلم أنّ الخيرَ كلَّه بيدِ الله، وأنّ رسله وأسبابه خاضعةٌ لأمره.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"العلمُ بأنّ العطاءَ من الله والأسبابُ خاضعةٌ لأمره."},"action":{"text":"اعلم أنّ كلَّ خيرٍ يأتيك إنما هو هبةٌ من الله، والأسبابُ والوسائطُ خاضعةٌ لأمره؛ فعلّق قلبك بالمعطي سبحانه لا بالأسباب، واطمئن إلى تدبيره."}},{"n":20,"reflection":{"text":"«قالت أنى يكون لي غلام ولم يمسسني بشر ولم أك بغيا» — قالت مريمُ متعجّبةً: كيف يكون لي ولدٌ ولم يقربني زوجٌ ولا كنت زانية؟ ففي هذا استغرابُها لخرقِ العادةِ مع براءتها التامّة، وحرصُها على نفي كلِّ ريبةٍ عن نفسها؛ فاحرص على براءةِ عرضك ونقاءِ سيرتك، وتعجّب من قدرةِ الله مع التسليمِ لها.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحرصُ على نقاءِ السيرةِ مع التسليمِ لقدرةِ الله."},"action":{"text":"احفظ عرضك ونقاءَ سيرتك حتى لا تُطرَق بريبة، كما نفت مريمُ عن نفسها كلَّ سوء؛ وسلّم لقدرةِ الله التي تخرق العاداتِ فتوجد الشيءَ بلا أسبابه المعتادة."}},{"n":21,"reflection":{"text":"«قال كذلك قال ربك هو علي هين ولنجعله آية للناس ورحمة منا وكان أمرا مقضيا» — قال المَلَك: هكذا الأمر، قال ربّك: خلقُه بلا أبٍ عليَّ سهل، ولنجعله علامةً على قدرتنا للناسِ ورحمةً منا بالعباد بما يدعوهم إليه، وكان أمرًا مقدَّرًا مفروغًا منه؛ ففي هذا أنّ خلقَ عيسى آيةٌ ورحمة، وأنّ قضاءَ الله نافذٌ لا يُردّ؛ فسلّم لقضاءِ الله النافذ، واعلم أنّ في خلقه آياتٍ ورحماتٍ للمعتبرين.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["هو علي هين","رحمة منا"],"heart_state":{"text":"التسليمُ لقضاءِ الله النافذ، وتأمّلُ آياتِه ورحمته."},"action":{"text":"سلّم لقضاءِ الله الذي لا يُردّ، وتأمّل في خلقه آياتِ قدرته ورحمته بعباده؛ فخلقُ عيسى بلا أبٍ آيةٌ ورحمة، وما قضى الله فهو كائنٌ لا محالة."}}]},{"title":"ولادةُ عيسى وتثبيتُ الله لمريم","range":[22,26],"theme":"مخاضُ مريمَ عند النخلة، وتسليةُ الله لها بالسريِّ والرطب","verses":[{"n":22,"reflection":{"text":"«فحملته فانتبذت به مكانا قصيا» — فحملت مريمُ بعيسى، فاعتزلت به مكانًا بعيدًا عن الناسِ خوفَ الفضيحةِ وطلبَ العزلة؛ ففي هذا أنّ المؤمنَ قد يُبتلى بما يشقّ عليه في مرضاةِ الله، وأنّ العزلةَ عند الفتنةِ سلامة؛ فاصبر على ما يقدّره الله عليك من الشدّة، والزم العزلةَ عند خوفِ الفتنة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الصبرُ على الشدّةِ المقدَّرة، والعزلةُ عند الفتنة."},"action":{"text":"اصبر على ما يقدّره الله عليك من ابتلاءٍ يشقّ عليك في سبيلِ طاعته، واعتزل مواطنَ الفتنةِ وقالةَ السوءِ ما استطعت؛ فالعزلةُ عند الشدّةِ حصنٌ للمؤمن."}},{"n":23,"reflection":{"text":"«فأجاءها المخاض إلى جذع النخلة قالت يا ليتني مت قبل هذا وكنت نسيا منسيا» — فألجأها وجعُ الولادةِ إلى جذعِ نخلةٍ تستند إليه، قالت من شدّةِ الكربِ وخوفِ تهمةِ الناس: يا ليتني متُّ قبل هذا وكنت شيئًا حقيرًا منسيًّا لا يُذكَر؛ ففي هذا شدّةُ ما لاقته، وأنّ خوفَ الفتنةِ في الدينِ أشدُّ من ألمِ الجسد؛ فاعلم أنّ الشدائدَ تمرّ، وأنّ بعدها فرجًا من الله، فلا يحملنّك الكربُ على تمنّي الموت.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الصبرُ عند اشتدادِ الكرب، وانتظارُ الفرج."},"action":{"text":"إذا اشتدّ بك الكربُ فتذكّر أنّ بعده فرجًا قريبًا من الله، ولا يحملنّك ضيقُ اللحظةِ على القنوطِ أو تمنّي الموت؛ فبعد عُسرِ مريمَ جاءها يُسرٌ ونداءٌ يطمئنها."}},{"n":24,"reflection":{"text":"«فناداها من تحتها ألا تحزني قد جعل ربك تحتك سريا» — فناداها عيسى (أو جبريل) من أسفلَ منها: لا تحزني، قد جعل ربّك تحتك نهرًا صغيرًا يجري تشربين منه؛ ففي هذا تعجيلُ الله بالفرجِ والتسليةِ بعد الكرب، وأنّ الله لا يترك أولياءه في شدّتهم؛ فأحسن الظنَّ بالله عند شدّتك، فهو يبدّل الحزنَ فرحًا والعسرَ يسرًا لمن توكّل عليه.","source":"تفسير السعدي","grade":"ma'thur"},"names":["ألا تحزني"],"heart_state":{"text":"إحسانُ الظنِّ بالله وانتظارُ تسليتِه بعد الكرب."},"action":{"text":"أحسن الظنَّ بربّك عند اشتدادِ حزنك، وثق أنه يعقب الكربَ فرجًا والحزنَ تسليةً؛ فقد بدّل حزنَ مريمَ طمأنينةً بنهرٍ يجري ونداءٍ «ألّا تحزني»، فارجُ منه مثل ذلك."}},{"n":25,"reflection":{"text":"«وهزي إليك بجذع النخلة تساقط عليك رطبا جنيا» — وحرّكي جذعَ النخلةِ يتساقط عليك رطبٌ ناضجٌ طريّ تأكلينه؛ ففي هذا أنّ الله أمرها بالأخذِ بالسببِ (الهزّ) مع أنه قادرٌ أن يُسقِطه بلا سبب، تعليمًا للأخذِ بالأسبابِ مع التوكّل؛ فخذ بالأسبابِ ولو يسيرةً، واعلم أنّ الرزقَ يأتي بسعيك مع تيسيرِ الله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الأخذُ بالأسبابِ مع التوكّلِ على الله في الرزق."},"action":{"text":"خذ بالأسبابِ في طلبِ رزقك ولو كانت يسيرةً كهزِّ الجذع، ثم توكّل على الله في تيسيرِها؛ فالله أجرى العادةَ أن يقرن الرزقَ بالسعي، فاسعَ وتوكّل ولا تتواكل."}},{"n":26,"reflection":{"text":"«فكلي واشربي وقري عينا فإما ترين من البشر أحدا فقولي إني نذرت للرحمن صوما فلن أكلم اليوم إنسيا» — فكلي من الرطبِ واشربي من النهرِ وطيبي نفسًا بمولودك، فإن رأيت أحدًا من الناسِ فأشيري أنك نذرت للرحمنِ صومًا (صمتًا) فلن تكلّمي اليومَ أحدًا؛ ففي هذا أنّ الصمتَ عن الجدالِ العقيمِ حكمة، وأنّ الله كفاها الدفاعَ عن نفسها بنطقِ وليدها؛ فأمسك لسانك عمّا لا ينفع، ودع الله يتولّى الدفاعَ عنك.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"حفظُ اللسانِ عن الجدالِ العقيم، وتفويضُ الدفاعِ لله."},"action":{"text":"أمسك لسانك عمّا لا طائلَ تحته من الجدالِ والمخاصمة، ودع الله يتولّى الدفاعَ عنك بما هو أبلغ؛ فمريمُ أُمِرت بالصمتِ فتكلّم عنها وليدُها بأبلغِ حجّة."}}]},{"title":"نطقُ عيسى في المهدِ ببراءتها وعبوديّته","range":[27,33],"theme":"اتّهامُ القومِ لمريم، ونطقُ عيسى الرضيعِ بعبوديّةِ الله ونبوّته","verses":[{"n":27,"reflection":{"text":"«فأتت به قومها تحمله قالوا يا مريم لقد جئت شيئا فريا» — فجاءت مريمُ بعيسى تحمله إلى قومها، فقالوا مستنكرين: يا مريمُ لقد فعلت أمرًا عظيمًا منكرًا مختلَقًا؛ ففي هذا ابتلاءُ العفيفةِ بألسنةِ الناس، وأنّ الصالحَ قد يُرمى بالباطل؛ فاصبر على ما يُقال فيك بالباطلِ إذا كنت بريئًا، فالله يظهر براءتك ولو بعد حين.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الصبرُ على تهمةِ الباطلِ والثقةُ بإظهارِ الله للحقّ."},"action":{"text":"إذا رُميت بالباطلِ وأنت بريء فاصبر ولا يهزّك قولُ الناس، وثق أنّ الله يُظهِر براءتك بطريقٍ لا تحتسبه؛ فبراءةُ مريمَ ظهرت بنطقِ رضيعٍ في المهد."}},{"n":28,"reflection":{"text":"«يا أخت هارون ما كان أبوك امرأ سوء وما كانت أمك بغيا» — يا شبيهةَ هارونَ في الصلاح (أو أختَ رجلٍ صالحٍ منهم)، ما كان أبوك رجلَ سوء، ولا كانت أمُّك زانية، فكيف جئت بهذا؟ ففي هذا أنهم عيّروها بمخالفةِ أصلها الصالح، وأنّ شرفَ الأصلِ يُطالَب صاحبُه بحفظه؛ فاحفظ شرفَ بيتك وأهلِ الصلاحِ من قبلك، ولا تأتِ ما يشينهم.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"حفظُ شرفِ البيتِ الصالحِ وعدمُ ما يشينه."},"action":{"text":"احفظ شرفَ أهلِ الصلاحِ من أهلك وسابقيك، ولا تأتِ ما يُعيَّرون به من أجلك؛ فالانتسابُ إلى الصالحين أمانةٌ تقتضي الاقتداءَ بهم لا مخالفتهم."}},{"n":29,"reflection":{"text":"«فأشارت إليه قالوا كيف نكلم من كان في المهد صبيا» — فأشارت مريمُ إلى عيسى أن كلّموه، فقالوا متعجّبين: كيف نكلّم طفلًا في المهدِ رضيعًا؟ ففي هذا ثقةُ مريمَ بوعدِ الله وإحالتُها الأمرَ إلى ما أعدّه لها من الآية، وأنّ الفرجَ يأتي من حيث لا يُحتسَب؛ فثق بوعدِ الله وأحل الأمرَ إليه، فمخرجُك قد يكون فيما يستبعده الناس.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الثقةُ بوعدِ الله وأنّ الفرجَ من حيث لا يُحتسَب."},"action":{"text":"ثق بوعدِ الله وفوّض إليه أمرك عند الشدّة، فمخرجُك قد يأتي من حيث يستبعده الناس؛ فمريمُ أحالت خصومها إلى رضيعٍ فكان نطقُه الآيةَ والبرهان."}},{"n":30,"reflection":{"text":"«قال إني عبد الله آتاني الكتاب وجعلني نبيا» — قال عيسى وهو في المهد: إني عبدُ الله (فأبطل بأوّلِ كلمةٍ دعوى ألوهيّته)، آتاني الإنجيلَ وجعلني نبيًّا؛ ففي هذا أنّ أوّلَ ما نطق به عيسى إثباتُ عبوديّته لله ونفيُ ما ادّعاه فيه الغالون، وأنّ العبوديةَ أشرفُ المقامات؛ فاعتزَّ بعبوديّتك لله، فهي أشرفُ وصفٍ وصف الله به أنبياءه.","source":"تفسير السعدي","grade":"ma'thur"},"names":["إني عبد الله"],"heart_state":{"text":"الاعتزازُ بعبوديّةِ الله، وأنها أشرفُ المقامات."},"action":{"text":"اعتزَّ بأنك عبدٌ لله وحده، فهي أشرفُ وصف؛ وأوّلُ ما نطق به عيسى «إني عبد الله»، فاجعل عبوديّتك لله تاجَ فخرك، وانفِ عن نفسك كلَّ كِبرٍ ودعوى."}},{"n":31,"reflection":{"text":"«وجعلني مباركا أين ما كنت وأوصاني بالصلاة والزكاة ما دمت حيا» — وجعلني نفّاعًا معلّمًا للخيرِ حيثما كنت، وأوصاني بالمحافظةِ على الصلاةِ وإيتاءِ الزكاةِ ما دمت حيًّا؛ ففي هذا أنّ العبدَ المبارَكَ من كان نفّاعًا أينما حلّ، وأنّ الصلاةَ والزكاةَ لازمتان مدى الحياة؛ فكن مبارَكًا نفّاعًا حيث كنت، والزم الصلاةَ والزكاةَ حتى الممات.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["وجعلني مباركا"],"heart_state":{"text":"أن يكون العبدُ نفّاعًا مبارَكًا ملازمًا للعبادة."},"action":{"text":"اجعل نفسك مبارَكًا نفّاعًا للناسِ بالعلمِ والخيرِ أينما حللت، والزم الصلاةَ والزكاةَ ما دمت حيًّا؛ فالبركةُ في نفعِ الخلق، ودوامُ العبادةِ عهدٌ إلى الموت."}},{"n":32,"reflection":{"text":"«وبرا بوالدتي ولم يجعلني جبارا شقيا» — وجعلني بارًّا بأمّي محسنًا إليها، ولم يجعلني متكبّرًا شقيًّا عاصيًا لربّي؛ ففي هذا عظمُ برِّ الوالدةِ حتى قرنه الله بعبادته، وأنّ الكِبرَ والعقوقَ شقاء؛ فبِرَّ والدتك خاصّةً، واحذر الكِبرَ والشقاء؛ فالبارُّ سعيد، والجبّارُ العاقُّ شقيّ.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"برُّ الوالدةِ خاصّةً، والبعدُ عن الكِبرِ والعقوق."},"action":{"text":"برَّ والدتك وأحسن إليها فحقُّها عظيم، واحذر الكِبرَ والعقوقَ فهما شقاء؛ فعيسى مع علوِّ قدره جعل برَّ أمِّه من أوّلِ ما افتخر به، فاقتدِ به في برِّها."}},{"n":33,"reflection":{"text":"«والسلام علي يوم ولدت ويوم أموت ويوم أبعث حيا» — والسلامةُ والأمنُ من الله عليَّ يومَ ولدت، ويومَ أموت، ويومَ أُبعَث حيًّا؛ ففي هذا طلبُ عيسى السلامةَ في المواطنِ الثلاثةِ العظام، وأنّ العبدَ الصالحَ يُحفَظ فيها؛ فاطلب من الله السلامةَ عند ولادتك في الدينِ وعند موتك وبعثك، بلزومِ العبوديةِ والتقوى.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"طلبُ السلامةِ في المواطنِ العظام بلزومِ العبودية."},"action":{"text":"اطلب من الله السلامةَ في أعظمِ المواطن: مبدأِ حياتك على الفطرة، وخاتمتِك على الإيمان، وبعثِك آمنًا؛ والزم العبوديةَ والتقوى التي بها تُنال هذه السلامة."}}]},{"title":"تنزيهُ الله عن الولد، وإنذارُ يومِ الحسرة","range":[34,40],"theme":"الحقُّ في شأنِ عيسى، وتنزيهُ الله، والتحذيرُ من يومِ القيامة","verses":[{"n":34,"reflection":{"text":"«ذلك عيسى ابن مريم قول الحق الذي فيه يمترون» — ذلك الموصوفُ بما تقدّم هو عيسى ابنُ مريمَ، قولُ الحقِّ الذي فيه يشكّ النصارى واليهودُ ويختلفون (فمن غالٍ ومن جافٍ)؛ ففي هذا أنّ الحقَّ في عيسى ما أخبر الله به: عبدٌ ورسول، لا ما قالته الفرقُ المختلفة؛ فالزم الحقَّ الوسطَ في كلِّ شأن، ولا تغلُ ولا تجفُ.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"لزومُ الحقِّ الوسطِ ونبذُ الغلوِّ والجفاء."},"action":{"text":"التزم في كلِّ أمرٍ الحقَّ الوسطَ الذي أخبر الله به، ولا تغلُ في تعظيمِ أحدٍ حتى ترفعه فوق قدره، ولا تجفُ فتبخسه حقّه؛ فالحقُّ بين الغلوِّ والتفريط."}},{"n":35,"reflection":{"text":"«ما كان لله أن يتخذ من ولد سبحانه إذا قضى أمرا فإنما يقول له كن فيكون» — ما ينبغي لله ولا يليق به أن يتّخذ ولدًا، تنزّه وتقدّس عن ذلك، إذا أراد أمرًا فإنما يقول له «كن» فيكون بلا والدةٍ ولا معاناة؛ ففي هذا تنزيهُ الله عن الولدِ وإثباتُ كمالِ قدرته بكلمةِ التكوين؛ فنزّه ربّك عن كلِّ نقص، واعلم أنّ خلقه بالكلمةِ لا بالتوالد، فأمرُه بين الكافِ والنون.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["سبحانه","كن فيكون"],"heart_state":{"text":"تنزيهُ الله عن الولدِ والنقص، وتعظيمُ قدرته."},"action":{"text":"نزّه ربّك عن الولدِ والصاحبةِ وكلِّ نقص، وعظّم قدرته التي توجد الأشياءَ بكلمةِ «كن»؛ فمن كان هذا شأنه لا يحتاج إلى ولدٍ ولا شريك، سبحانه وتعالى."}},{"n":36,"reflection":{"text":"«وإن الله ربي وربكم فاعبدوه هذا صراط مستقيم» — قال عيسى: وإنّ الله ربّي وربّكم جميعًا فاعبدوه وحده، هذا الذي أدعوكم إليه هو الطريقُ المستقيمُ الموصلُ إلى الله؛ ففي هذا أنّ دعوةَ عيسى كدعوةِ الأنبياءِ كلِّهم: توحيدُ الله وعبادتُه، وأنّ التوحيدَ هو الصراطُ المستقيم؛ فأخلص العبادةَ لربّك وحده، فذلك الصراطُ المستقيمُ الذي دعت إليه الرسل.","source":"تفسير السعدي","grade":"ma'thur"},"names":["هذا صراط مستقيم"],"heart_state":{"text":"إخلاصُ العبادةِ لله، ولزومُ صراطِ التوحيد."},"action":{"text":"أخلص عبادتك لله ربِّك وربِّ كلِّ شيء، فذلك هو الصراطُ المستقيمُ الذي دعا إليه عيسى وكلُّ نبيّ؛ ولا تحد عنه يمنةً ولا يسرةً إلى شركٍ أو بدعة."}},{"n":37,"reflection":{"text":"«فاختلف الأحزاب من بينهم فويل للذين كفروا من مشهد يوم عظيم» — فاختلفت الفرقُ في عيسى بعد وضوحِ الحقّ (فمنهم من قال إلهٌ، ومنهم من قال ابنُ الله، ومنهم من كذّب)، فهلاكٌ وعذابٌ شديدٌ للذين كفروا من حضورِ يومِ القيامةِ العظيمِ وأهواله؛ ففي هذا أنّ الاختلافَ في الحقِّ بعد بيانِه ضلال، وأنّ للكافرين موقفًا عظيمًا مهولًا؛ فاحذر الاختلافَ المذمومَ في الحقِّ الواضح، واستعدَّ لموقفِ ذلك اليومِ العظيم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من الاختلافِ في الحقِّ الواضح، والاستعدادُ للقيامة."},"action":{"text":"احذر الاختلافَ والتفرّقَ في الحقِّ بعد بيانه، والزم ما دلّ عليه الوحيُ بلا غلوٍّ ولا تكذيب؛ واستعدَّ لموقفِ يومٍ عظيمٍ تُهوِّل الكافرَ أهوالُه، فاعمل ليومك."}},{"n":38,"reflection":{"text":"«أسمع بهم وأبصر يوم يأتوننا لكن الظالمون اليوم في ضلال مبين» — ما أسمعَهم وأبصرَهم يوم القيامةِ حين يأتوننا! يسمعون ويبصرون الحقَّ حيث لا ينفعهم، لكنّ الظالمين اليومَ في الدنيا في ضلالٍ ظاهرٍ صمٌّ عن الحقِّ عُميٌ عنه؛ ففي هذا أنّ إبصارَ الحقِّ يومَ القيامةِ لا ينفع، وأنّ الانتفاعَ بالسمعِ والبصرِ إنما هو اليوم؛ فاسمع الحقَّ وأبصره اليومَ حيث ينفعك، قبل يومٍ تبصره ولا ينفع.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"انتهازُ الحياةِ لسماعِ الحقِّ وإبصارِه قبل فواته."},"action":{"text":"اسمع الحقَّ وأبصره واعمل به اليومَ في دنياك حيث ينفعك، قبل يومٍ يبصر فيه الظالمُ الحقَّ ويسمعه فلا يجديه شيئًا؛ فالغنيمةُ في الانتفاعِ الآن."}},{"n":39,"reflection":{"text":"«وأنذرهم يوم الحسرة إذ قضي الأمر وهم في غفلة وهم لا يؤمنون» — وحذّرهم يا محمد يومَ الحسرةِ والندامةِ حين يُقضى الأمرُ فيدخل أهلُ الجنةِ الجنةَ وأهلُ النارِ النار، وهم اليومَ في غفلةٍ عن هذا اليومِ لا يؤمنون به؛ ففي هذا أنّ أعظمَ الحسرةِ يومَ القيامةِ على من فرّط، وأنّ الغفلةَ عن الآخرةِ سببُ الحسرة؛ فانفض عنك الغفلة، واعمل لذلك اليومِ لئلا تندم حيث لا ينفع الندم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"طردُ الغفلةِ والعملُ لئلا يقع الندمُ يومَ الحسرة."},"action":{"text":"أيقظ قلبك من الغفلةِ عن الآخرة، واعمل من الصالحاتِ ما يقيك حسرةَ يومِ القيامة؛ فأشدُّ الحسرةِ على من فرّط في أيامِ المهلة، فبادر قبل أن يُقضى الأمر."}},{"n":40,"reflection":{"text":"«إنا نحن نرث الأرض ومن عليها وإلينا يرجعون» — إنا نحن نرثُ الأرضَ ومن عليها، فيبيد الخلقُ ويبقى الله وحده، وإلينا يُرجَعون للحسابِ والجزاء؛ ففي هذا أنّ كلَّ شيءٍ فانٍ والله الباقي، وأنّ المرجعَ إليه وحده؛ فلا تركن إلى دنيا تزول، واعمل لِما ترجع به إلى الله، فإليه المصيرُ والمآب.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"استحضارُ فناءِ الدنيا والرجوعِ إلى الله وحده."},"action":{"text":"لا تغترَّ بدنيا يرثها الله بعد أهلها، واستحضر أنك راجعٌ إلى ربّك للحساب؛ فاجعل عملك زادًا لذلك الرجوع، وعلّق قلبك بالباقي لا بالفاني."}}]},{"title":"إبراهيمُ ودعوةُ أبيه برفق","range":[41,45],"theme":"مناظرةُ إبراهيمَ لأبيه في عبادةِ الأصنام بأدبٍ ولين","verses":[{"n":41,"reflection":{"text":"«واذكر في الكتاب إبراهيم إنه كان صديقا نبيا» — واذكر في القرآنِ إبراهيمَ، إنه كان كثيرَ الصدقِ بالغَ التصديقِ بآياتِ الله، نبيًّا مرسلًا؛ ففي هذا أنّ الصدّيقيةَ أعلى مراتبِ الصدق، وأنها وصفُ إبراهيمَ الخليل؛ فاجعل الصدقَ ديدنك في القولِ والعملِ والاعتقاد، فبالصدقِ تُنال أعلى المراتب.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["صديقا نبيا"],"heart_state":{"text":"لزومُ الصدقِ حتى بلوغِ مرتبةِ الصدّيقية."},"action":{"text":"الزم الصدقَ في قولك وعملك واعتقادك حتى تبلغ مرتبةَ الصدّيقين، فقد وصف الله بها إبراهيمَ خليله؛ فالصدقُ طريقُ البِرِّ وأعلى منازلِ العبودية."}},{"n":42,"reflection":{"text":"«إذ قال لأبيه يا أبت لم تعبد ما لا يسمع ولا يبصر ولا يغني عنك شيئا» — حين قال لأبيه بلطفٍ: يا أبتِ لِمَ تعبد صنمًا لا يسمع دعاءك ولا يبصر عبادتك ولا يدفع عنك ضرًّا ولا يجلب نفعًا؟ ففي هذا أدبُ إبراهيمَ في دعوةِ أبيه بقوله «يا أبت»، وحجّتُه العقليةُ على بطلانِ عبادةِ ما لا ينفع ولا يضرّ؛ فادعُ إلى الحقِّ بالرفقِ والحجّة، وابدأ بالأقربين برفقٍ ولين.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الدعوةُ بالرفقِ والحجّة، والبَداءةُ بالأقربين."},"action":{"text":"ادعُ إلى الحقِّ بالكلمةِ الليّنةِ والحجّةِ الواضحة، وابدأ بأقربِ الناسِ إليك برفقٍ وأدبٍ كما خاطب إبراهيمُ أباه بـ«يا أبت»؛ فالرفقُ في الدعوةِ أدعى للقبول."}},{"n":43,"reflection":{"text":"«يا أبت إني قد جاءني من العلم ما لم يأتك فاتبعني أهدك صراطا سويا» — يا أبتِ إني أُوتيتُ من العلمِ بالله ودينه ما لم تُؤتَه، فاتّبعني أدلّك على طريقٍ مستقيمٍ معتدل؛ ففي هذا تواضعُ الداعيةِ مع بيانِ ما عنده من الحقّ، ودعوةُ المدعوِّ إلى الاتّباعِ بالحجّة؛ فادعُ الناسَ إلى ما تعلم من الحقِّ بتواضعٍ وشفقة، لا بتعالٍ واستطالة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الدعوةُ إلى الحقِّ بتواضعٍ وشفقةٍ لا بتعالٍ."},"action":{"text":"ادعُ الناسَ إلى ما علمته من الحقِّ بتواضعٍ وشفقةٍ عليهم، مبيّنًا لهم الطريقَ المستقيم؛ ولا تدعُهم بتعالٍ أو ازدراء، فإبراهيمُ دعا أباه مرشدًا مشفقًا لا متكبّرًا."}},{"n":44,"reflection":{"text":"«يا أبت لا تعبد الشيطان إن الشيطان كان للرحمن عصيا» — يا أبتِ لا تُطِع الشيطانَ فيما يزيّنه لك من عبادةِ الأصنام، فإنّ الشيطانَ كان للرحمنِ عاصيًا متمرّدًا؛ ففي هذا أنّ طاعةَ الشيطانِ في المعصيةِ عبادةٌ له، وأنّ الحذرَ منه واجب؛ فلا تُطِع الشيطانَ في شيءٍ من معصيةِ الله، فطاعتُه في المعصيةِ عبوديةٌ لعدوٍّ عاصٍ.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من طاعةِ الشيطان، فطاعتُه في المعصيةِ عبادة."},"action":{"text":"لا تُطِع الشيطانَ في شيءٍ يدعوك إليه من معصيةِ الله، فإنّ طاعته فيها عبادةٌ له؛ واعصِ من عصى الرحمنَ ولا تتّبع خطواته، فهو عدوٌّ يدعوك إلى الهلاك."}},{"n":45,"reflection":{"text":"«يا أبت إني أخاف أن يمسك عذاب من الرحمن فتكون للشيطان وليا» — يا أبتِ إني أخشى إن متَّ على الشركِ أن يصيبك عذابٌ من الرحمنِ فتصير قرينًا للشيطانِ في النار؛ ففي هذا شفقةُ إبراهيمَ على أبيه وخوفُه عليه من العذاب، وأنّ الموالاةَ للشيطانِ عاقبتها معه في النار؛ فأشفِق على من تدعوه واخشَ عليه العاقبة، فالشفقةُ تحمل الداعيَ على النصح.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الشفقةُ على المدعوِّ والخوفُ عليه من سوءِ العاقبة."},"action":{"text":"أشفِق على من تدعوه إلى الحقّ، وليكن باعثُك خوفَك عليه من عذابِ الله لا مجردَ المخاصمة؛ فإبراهيمُ دعا أباه رحمةً به وخوفًا عليه أن يكون للشيطانِ وليًّا."}}]},{"title":"صبرُ إبراهيمَ واعتزالُه، وعطاءُ الله له","range":[46,50],"theme":"جفاءُ الأبِ ورفقُ إبراهيم، واعتزالُه لهم، فوهبه الله ذريّةً أنبياء","verses":[{"n":46,"reflection":{"text":"«قال أراغب أنت عن آلهتي يا إبراهيم لئن لم تنته لأرجمنك واهجرني مليا» — قال أبوه: أمعرِضٌ أنت عن عبادةِ آلهتي يا إبراهيم؟ لئن لم تكفَّ عن عيبها لأرمينّك بالحجارةِ أو لأشتمنّك، وابعُد عني زمنًا طويلًا؛ ففي هذا مقابلةُ الأبِ للنصحِ بالتهديدِ والغلظة، وأنّ الداعيَ قد يُقابَل بالأذى؛ فوطّن نفسك على أنّ دعوتك قد تُقابَل بالجفاء، ولا يصدّنك ذلك عن الحقّ.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"توطينُ النفسِ على أذى الدعوة، والثباتُ على الحقّ."},"action":{"text":"وطّن نفسك على أنّ دعوتك إلى الحقِّ قد تُقابَل بالتهديدِ والجفاءِ ولو من الأقربين، ولا يصدّنك ذلك عن المضيِّ في الحقِّ والصبرِ عليه؛ فالثباتُ ثمرةُ اليقين."}},{"n":47,"reflection":{"text":"«قال سلام عليك سأستغفر لك ربي إنه كان بي حفيا» — قال إبراهيمُ بحلمٍ ولين: سلامٌ عليك (سلامُ متاركةٍ لا تحيّةِ إكرام)، سأدعو الله أن يغفر لك ويهديك، إنه كان بي لطيفًا كثيرَ الإحسانِ يجيب دعائي؛ ففي هذا مقابلةُ الإساءةِ بالحلمِ والدعاءِ بالهداية، وحسنُ ظنِّ إبراهيمَ بربّه؛ فقابل جفاءَ الناسِ بالحلمِ والدعاءِ لهم، وأحسن الظنَّ بالله في إجابته.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["سلام عليك","كان بي حفيا"],"heart_state":{"text":"مقابلةُ الإساءةِ بالحلمِ والدعاء، وحسنُ الظنِّ بالله."},"action":{"text":"قابل من أساء إليك بالحلمِ والكلمةِ الطيّبةِ والدعاءِ له بالهداية، كما قال إبراهيمُ لأبيه «سلام عليك سأستغفر لك ربي»؛ وأحسن الظنَّ بالله أنه يجيب دعاءك."}},{"n":48,"reflection":{"text":"«وأعتزلكم وما تدعون من دون الله وأدعو ربي عسى ألا أكون بدعاء ربي شقيا» — وأفارقكم وأترك ما تعبدون من دون الله، وأدعو ربّي وحده، راجيًا ألّا أكون بدعائي إياه محرومًا خائبًا كما خبتم بعبادةِ الأصنام؛ ففي هذا مشروعيةُ اعتزالِ أهلِ الباطلِ ومعبوداتهم، وحسنُ الرجاءِ في إجابةِ الله؛ فاعتزل أهلَ الباطلِ إذا لم يستجيبوا، والزم دعاءَ ربّك راجيًا قبوله.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اعتزالُ أهلِ الباطل، ولزومُ الدعاءِ برجاءِ القبول."},"action":{"text":"إذا لم يُجدِ النصحُ مع أهلِ الباطلِ فاعتزلهم ومعبوداتِهم، والزم دعاءَ ربّك وحده راجيًا ألّا يخيّبك؛ فالاعتزالُ حفظٌ للدين، والدعاءُ صلةٌ بالله لا تخيب."}},{"n":49,"reflection":{"text":"«فلما اعتزلهم وما يعبدون من دون الله وهبنا له إسحاق ويعقوب وكلا جعلنا نبيا» — فلما فارقهم وما يعبدون عوّضه الله خيرًا: وهبنا له إسحاقَ ابنًا ويعقوبَ حفيدًا، وجعلنا كلًّا منهما نبيًّا؛ ففي هذا أنّ من ترك شيئًا لله عوّضه الله خيرًا منه، وأنّ الهجرةَ في الله تُثمر الذريّةَ الصالحة؛ فمن فارق أهلَ الباطلِ لله أبدله الله صحبةً صالحةً وخيرًا كثيرًا؛ فاترك لله يعوّضك.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الثقةُ بأنّ من ترك شيئًا لله عوّضه خيرًا منه."},"action":{"text":"اترك ما يلزمك تركُه لله ــ من صحبةٍ أو مألوفٍ يضرّ دينك ــ واثقًا بأنّ الله يعوّضك خيرًا منه؛ فإبراهيمُ لمّا اعتزل أهله لله وهبه ذريّةً أنبياء."}},{"n":50,"reflection":{"text":"«ووهبنا لهم من رحمتنا وجعلنا لهم لسان صدق عليا» — ووهبنا لإبراهيمَ وذريّته من رحمتنا في الدنيا والآخرة، وجعلنا لهم ثناءً حسنًا رفيعًا باقيًا على ألسنةِ الناسِ في كلِّ الأمم؛ ففي هذا أنّ عاقبةَ الصدقِ مع الله رحمةٌ وذكرٌ حسنٌ باقٍ، وأنّ الثناءَ الصادقَ من الله؛ فاصدق مع الله يجعل لك القبولَ والذكرَ الحسنَ في الناس، فالصيتُ الحسنُ من ثمارِ الإخلاص.","source":"تفسير السعدي","grade":"ma'thur"},"names":["لسان صدق عليا"],"heart_state":{"text":"طلبُ رحمةِ الله والذكرِ الحسنِ بالصدقِ والإخلاص."},"action":{"text":"اصدق مع الله وأخلص له، واطلب منه رحمتَه والقبولَ في الأرض؛ فمن صدق مع الله رزقه الرحمةَ ولسانَ صدقٍ يُثنى به عليه، فالذكرُ الحسنُ عطاءٌ من الله لأهلِ الإخلاص."}}]},{"title":"موسى وهارونُ وإسماعيلُ وإدريس","range":[51,57],"theme":"ذكرُ موسى المُخلَصِ النجيّ، وإسماعيلَ صادقِ الوعد، وإدريسَ المرفوع","verses":[{"n":51,"reflection":{"text":"«واذكر في الكتاب موسى إنه كان مخلصا وكان رسولا نبيا» — واذكر في القرآنِ موسى، إنه كان مُخلَصًا اختاره الله واصطفاه وأخلص عبادته، وكان رسولًا نبيًّا؛ ففي هذا فضلُ الإخلاصِ الذي به يُصطفى العبد، وأنّ موسى بلغ مرتبةَ الاصطفاء؛ فأخلص عملك لله وحده، فبالإخلاصِ يرفع الله العبدَ ويصطفيه.","source":"تفسير السعدي","grade":"ma'thur"},"names":["مخلصا"],"heart_state":{"text":"طلبُ الإخلاصِ الذي به يصطفي الله عبده."},"action":{"text":"أخلص أعمالك كلَّها لله وحده لا تبتغي بها إلا وجهه، فبالإخلاصِ يصطفي الله عبده ويرفعه؛ فكان موسى مُخلَصًا مصطفًى، فاجعل الإخلاصَ روحَ عملك."}},{"n":52,"reflection":{"text":"«وناديناه من جانب الطور الأيمن وقربناه نجيا» — وكلّمناه من الجانبِ الأيمنِ من جبلِ الطورِ، وقرّبناه مناجيًا نكلّمه ويسمع كلامنا؛ ففي هذا شرفُ موسى بتكليمِ الله له، وأنّ القربَ من الله أعظمُ منزلة؛ فاطلب القربَ من الله بالطاعةِ والمناجاة، فأشرفُ ما يناله العبدُ قربُ ربّه ومناجاتُه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"طلبُ القربِ من الله بالطاعةِ والمناجاة."},"action":{"text":"اطلب القربَ من الله بمناجاته في صلاتك ودعائك وذكرك، فأشرفُ منازلِ العبدِ قربُه من ربّه؛ فقد قرّب الله موسى نجيًّا يكلّمه، فتعرّض لهذا القربِ بالطاعة."}},{"n":53,"reflection":{"text":"«ووهبنا له من رحمتنا أخاه هارون نبيا» — ووهبنا لموسى من رحمتنا أخاه هارونَ نبيًّا يعينه ويؤازره في الرسالة؛ ففي هذا أنّ من رحمةِ الله أن يهيّئ للعبدِ عونًا صالحًا، وأنّ الإعانةَ على الحقِّ نعمة؛ فاطلب من الله عونًا صالحًا يعينك على الخير، واشكر من جعله الله عونًا لك، فالمعينُ على الحقِّ رحمة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"شكرُ العونِ الصالح، وطلبُه من الله على الخير."},"action":{"text":"اطلب من الله رفيقًا صالحًا يعينك على الحقِّ والدعوةِ إليه، واشكره على من سخّره عونًا لك؛ فمن رحمةِ الله بموسى أن آزره بأخيه هارون، فالمعينُ نعمةٌ تُشكَر."}},{"n":54,"reflection":{"text":"«واذكر في الكتاب إسماعيل إنه كان صادق الوعد وكان رسولا نبيا» — واذكر في القرآنِ إسماعيلَ، إنه كان صادقَ الوعدِ لا يعِد شيئًا إلا وفى به، وكان رسولًا نبيًّا؛ ففي هذا مدحُ صدقِ الوعدِ حتى أُفرِد به إسماعيلُ ثناءً، وأنه من صفاتِ الأنبياء؛ فاصدق في وعدك ولا تُخلِف، فصدقُ الوعدِ من الإيمانِ وخلقِ الأنبياء.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["صادق الوعد"],"heart_state":{"text":"الوفاءُ بالوعدِ وصدقُه، فهو خلقُ الأنبياء."},"action":{"text":"إذا وعدت فأوفِ بوعدك ولا تُخلِف، فصدقُ الوعدِ خلقٌ أثنى الله به على إسماعيل؛ واحذر خُلفَ الوعدِ فإنه من علاماتِ النفاق، والوفاءُ من كمالِ الإيمان."}},{"n":55,"reflection":{"text":"«وكان يأمر أهله بالصلاة والزكاة وكان عند ربه مرضيا» — وكان إسماعيلُ يأمر أهله بالصلاةِ وإيتاءِ الزكاة، فبدأ بإصلاحِ بيته، وكان عند ربّه مرضيًّا في أقواله وأعماله؛ ففي هذا وجوبُ العنايةِ بأهلِ البيتِ وأمرِهم بالطاعة، وأنّ رضا الله غايةُ المطلوب؛ فمُر أهلك بالصلاةِ والزكاةِ واصبر عليها، واطلب رضا الله فهو أعظمُ الغايات.","source":"تفسير السعدي","grade":"ma'thur"},"names":["عند ربه مرضيا"],"heart_state":{"text":"العنايةُ بأهلِ البيتِ بالطاعة، وطلبُ رضا الله."},"action":{"text":"مُر أهلك وولدك بالصلاةِ والزكاةِ والطاعةِ واصبر على ذلك، فأنت راعٍ مسؤولٌ عنهم؛ واجعل غايتك رضا الله فهو أعظمُ ما يُطلَب، به كان إسماعيلُ مرضيًّا عند ربّه."}},{"n":56,"reflection":{"text":"«واذكر في الكتاب إدريس إنه كان صديقا نبيا» — واذكر في القرآنِ إدريسَ، إنه كان صدّيقًا كثيرَ الصدقِ والتصديق، نبيًّا؛ ففي هذا أنّ الصدّيقيةَ وصفٌ متكرّرٌ لأهلِ النبوّة، وأنها مرتبةٌ عليا؛ فاطلب الصدقَ حتى تُعرَف به، فالصدّيقُ من امتلأ صدقًا فصار وصفًا لازمًا له.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"طلبُ مرتبةِ الصدقِ الراسخِ حتى تصير سجيّة."},"action":{"text":"اطلب أن يصير الصدقُ سجيّةً لك في القولِ والعملِ والوعدِ حتى تُعرَف به، فالصدّيقيةُ مرتبةٌ عليا بلغها إدريسُ وإبراهيمُ؛ فتحرَّ الصدقَ في كلِّ شأنك."}},{"n":57,"reflection":{"text":"«ورفعناه مكانا عليا» — ورفعنا إدريسَ منزلةً عاليةً شريفةً (رفعةَ قدرٍ ومكانةٍ عند الله)؛ ففي هذا أنّ الله يرفع أهلَ الصدقِ والطاعةِ رفعةً في الدنيا والآخرة، وأنّ العلوَّ الحقيقيَّ علوُّ المنزلةِ عند الله؛ فاطلب العلوَّ عند الله بالطاعةِ والصدق، لا علوَّ الدنيا الزائل.","source":"تفسير السعدي","grade":"ma'thur"},"names":["مكانا عليا"],"heart_state":{"text":"طلبُ الرفعةِ عند الله بالطاعةِ والصدق."},"action":{"text":"اطلب العلوَّ الحقيقيَّ وهو رفعةُ المنزلةِ عند الله بالطاعةِ والإخلاصِ والصدق، لا علوَّ الجاهِ والدنيا؛ فالله رفع إدريسَ مكانًا عليًّا بصدقه وعبادته."}}]},{"title":"سجدةُ الأنبياءِ، وذمُّ الخَلَفِ المضيّع","range":[58,63],"theme":"خشوعُ الأنبياءِ عند الآيات، وضياعُ من بعدهم للصلاة، وبشرى التائبين","verses":[{"n":58,"reflection":{"text":"«أولئك الذين أنعم الله عليهم من النبيين من ذرية آدم وممن حملنا مع نوح ومن ذرية إبراهيم وإسرائيل وممن هدينا واجتبينا إذا تتلى عليهم آيات الرحمن خروا سجدا وبكيا» — أولئك المذكورون هم الذين أنعم الله عليهم بالنبوّةِ من ذريّةِ آدمَ ونوحٍ وإبراهيمَ ويعقوب، وممّن هداهم الله واصطفاهم، كانوا إذا سمعوا آياتِ الرحمنِ خرّوا ساجدين باكين خشوعًا؛ ففي هذا أنّ علامةَ المُنعَمِ عليهم الخشوعُ والبكاءُ عند آياتِ الله؛ فتأثّر بآياتِ الله عند سماعها بالخشوعِ والدمعة، واقتدِ بالأنبياءِ في خضوعهم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["آيات الرحمن"],"heart_state":{"text":"الخشوعُ والبكاءُ عند سماعِ آياتِ الله."},"action":{"text":"لِن قلبك عند سماعِ آياتِ الله واخشع لها، واستدرَّ الدمعةَ بتدبّرها، واسجد لله متأثّرًا؛ فهذا هديُ الأنبياءِ المُنعَمِ عليهم: خرّوا سجّدًا وبكيًّا عند آياتِ الرحمن."}},{"n":59,"reflection":{"text":"«فخلف من بعدهم خلف أضاعوا الصلاة واتبعوا الشهوات فسوف يلقون غيا» — فجاء من بعدِ هؤلاءِ الأنبياءِ الصالحين قومٌ سوءٌ ضيّعوا الصلاةَ (بتركها أو تأخيرها عن وقتها) واتّبعوا شهواتِ أنفسهم، فسوف يلقَون شرًّا وخسرانًا (أو واديًا في جهنم)؛ ففي هذا أنّ إضاعةَ الصلاةِ واتّباعَ الشهواتِ طريقُ الهلاك، وأنّ حفظَ الصلاةِ فارقٌ بين أهلِ الهدى والغيّ؛ فحافظ على صلاتك في أوقاتها، واحذر أن تتبع شهوةً تصدّك عنها.","source":"تفسير السعدي","grade":"ma'thur"},"names":["أضاعوا الصلاة"],"heart_state":{"text":"المحافظةُ على الصلاةِ والحذرُ من إضاعتِها للشهوات."},"action":{"text":"حافظ على صلاتك في أوقاتها بأركانها وخشوعها، واحذر أن تشغلك الشهواتُ عنها أو تؤخّرها عن وقتها؛ فإضاعةُ الصلاةِ رأسُ الغيّ، وحفظُها أوّلُ علاماتِ الصلاح."}},{"n":60,"reflection":{"text":"«إلا من تاب وآمن وعمل صالحا فأولئك يدخلون الجنة ولا يظلمون شيئا» — لكن من تاب من تضييعِ الصلاةِ واتّباعِ الشهوات، وآمن وعمل صالحًا، فأولئك يدخلون الجنةَ ولا يُنقَصون من ثوابِ أعمالهم شيئًا؛ ففي هذا سعةُ رحمةِ الله بفتحِ بابِ التوبة، وأنّ التائبَ الصادقَ يلحق بالصالحين؛ فمهما فرّطت فبابُ التوبةِ مفتوح، فتب وآمن واعمل صالحًا تُدرِك الجنة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"المبادرةُ بالتوبةِ والعملِ الصالحِ رجاءَ الجنة."},"action":{"text":"مهما فرّطت في جنبِ الله فبادر بالتوبةِ الصادقةِ والإيمانِ والعملِ الصالح، فبابُ الله مفتوح؛ فالتائبُ العاملُ يدخل الجنةَ ولا يُظلَم من أجرِه شيئًا، فلا تقنط."}},{"n":61,"reflection":{"text":"«جنات عدن التي وعد الرحمن عباده بالغيب إنه كان وعده مأتيا» — يدخلون جناتِ إقامةٍ دائمةٍ وعدها الرحمنُ عباده وهم لم يروها (آمنوا بها غيبًا)، إنّ وعده كائنٌ لا محالةَ آتٍ؛ ففي هذا أنّ الإيمانَ بالغيبِ سببُ نيلِ الوعد، وأنّ وعدَ الله حقٌّ لا يتخلّف؛ فآمن بوعدِ الله وإن لم تره، واعمل له واثقًا بأنه آتٍ لا محالة.","source":"تفسير السعدي","grade":"ma'thur"},"names":["وعده مأتيا"],"heart_state":{"text":"الإيمانُ بوعدِ الله بالغيبِ والثقةُ بتحقّقه."},"action":{"text":"آمن بما وعد الله من الجنةِ والنعيمِ وإن لم تره، واعمل له واثقًا بأنّ وعده حقٌّ آتٍ لا يتخلّف؛ فالإيمانُ بالغيبِ والعملُ له سبيلُ الفوزِ بجناتِ عدن."}},{"n":62,"reflection":{"text":"«لا يسمعون فيها لغوا إلا سلاما ولهم رزقهم فيها بكرة وعشيا» — لا يسمعون في الجنةِ باطلًا ولا كلامًا مؤذيًا، إلا تسليمًا يحيّي بعضهم بعضًا، ولهم رزقهم فيها دائمًا في مقدارِ الصباحِ والمساء؛ ففي هذا كمالُ نعيمِ الجنةِ بسلامتها من كلِّ لغوٍ ودوامِ رزقها؛ فاعمل لدارِ السلامِ التي لا لغوَ فيها ولا أذى، وطهّر مجلسك في الدنيا من اللغوِ استعدادًا لها.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ لدارِ السلام، وتطهيرُ المجالسِ من اللغو."},"action":{"text":"اعمل لجنةٍ لا يُسمَع فيها إلا السلام، وطهّر مجالسك في الدنيا من اللغوِ والباطلِ والأذى؛ فمن عوّد لسانه ومجلسه الطيبَ في الدنيا هُيّئ لدارٍ لا لغوَ فيها."}},{"n":63,"reflection":{"text":"«تلك الجنة التي نورث من عبادنا من كان تقيا» — تلك الجنةُ الموصوفةُ نجعلها ميراثًا لمن كان تقيًّا من عبادنا يخشى الله ويعمل بطاعته؛ ففي هذا أنّ الجنةَ تُنال بالتقوى، وأنها ميراثُ المتّقين؛ فالزم التقوى في السرِّ والعلن، فبها تورَّث الجنةُ، ولا سبيلَ إليها إلا بها.","source":"تفسير السعدي","grade":"ma'thur"},"names":["من كان تقيا"],"heart_state":{"text":"لزومُ التقوى التي بها تورَّث الجنة."},"action":{"text":"الزم تقوى الله في سرّك وعلانيتك بامتثالِ أمره واجتنابِ نهيه، فبالتقوى تورَّث الجنة؛ فاجعل التقوى زادك ورأسَ مالك، فهي مفتاحُ دارِ الخلود."}}]},{"title":"تنزّلُ الوحيِ بأمرِ الله، والأمرُ بالعبادةِ والصبر","range":[64,65],"theme":"أنّ الملائكةَ لا تنزل إلا بأمرِ الله، والأمرُ بعبادتِه والاصطبارِ لها","verses":[{"n":64,"reflection":{"text":"«وما نتنزل إلا بأمر ربك له ما بين أيدينا وما خلفنا وما بين ذلك وما كان ربك نسيا» — تقول الملائكةُ: وما ننزل من السماءِ إلا بأمرِ ربّك، له علمُ ما أمامنا من أمرِ الآخرةِ وما خلفنا من الدنيا وما بين ذلك، وما كان ربّك ناسيًا لشيءٍ من عباده وأعمالهم؛ ففي هذا أنّ الأمرَ كلَّه بيدِ الله وعلمِه، وأنه لا ينسى عبده؛ فاطمئن إلى أنّ الله لا ينساك ولا يغفل عنك، فامضِ في طاعته موقنًا بإحاطته.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["وما كان ربك نسيا"],"heart_state":{"text":"الاطمئنانُ إلى أنّ الله لا ينسى عبده ولا يغفل عنه."},"action":{"text":"اطمئن إلى أنّ ربّك محيطٌ بكلِّ أمرك لا ينساك ولا يغفل عنك، وأنّ كلَّ شيءٍ بأمره وعلمه؛ فامضِ في طاعته صابرًا، واثقًا أنّ من لا ينساك يتولّى أمرك ويجزيك."}},{"n":65,"reflection":{"text":"«رب السماوات والأرض وما بينهما فاعبده واصطبر لعبادته هل تعلم له سميا» — هو ربُّ السماواتِ والأرضِ وما بينهما ومالكها ومدبّرها، فاعبده وحده واصبر على عبادته ولازمها، هل تعلم له مثيلًا أو سميًّا يستحقُّ العبادة؟ لا أحد؛ ففي هذا الأمرُ بإفرادِ الله بالعبادةِ والصبرِ عليها لأنه لا نظيرَ له؛ فاعبد ربّك وحده واصبر على طاعته، فلا سميَّ له ولا مثيلَ يستحقُّ أن يُعبَد.","source":"تفسير السعدي","grade":"ma'thur"},"names":["رب السماوات والأرض","هل تعلم له سميا"],"heart_state":{"text":"إفرادُ الله بالعبادةِ والصبرُ على طاعته."},"action":{"text":"أفرِد ربّك بالعبادةِ فلا مثيلَ له ولا سميّ، واصبر على طاعته ولازمها ولو شقّت على النفس؛ فمن عرف أنه لا ندَّ لله هان عليه الصبرُ على عبادةِ من هذا شأنه."}}]},{"title":"إنكارُ البعثِ والردُّ عليه، وورودُ النار","range":[66,72],"theme":"استبعادُ الإنسانِ للبعث، وحشرُ الكفارِ حولَ جهنم، ونجاةُ المتّقين","verses":[{"n":66,"reflection":{"text":"«ويقول الإنسان أإذا ما مت لسوف أخرج حيا» — ويقول الكافرُ منكرًا مستبعدًا: أإذا متُّ سوف أُخرَج من قبري حيًّا؟ ففي هذا استبعادُ الجاحدِ للبعثِ لعدمِ تدبّره لقدرةِ الله؛ فلا تكن ممّن يستبعد قدرةَ الله على البعث، بل أيقن به فهو حقٌّ دلّ عليه العقلُ والنقل.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بالبعثِ ونبذُ استبعادِه."},"action":{"text":"أيقن بالبعثِ بعد الموتِ يقينًا لا يخالطه شكّ، ولا تكن كالجاحدِ الذي يستبعده؛ فالذي بدأ خلقك قادرٌ على إعادتك، والبعثُ حقٌّ دلّ عليه الوحيُ والعقل."}},{"n":67,"reflection":{"text":"«أولا يذكر الإنسان أنا خلقناه من قبل ولم يك شيئا» — أولا يتذكّر هذا المنكِرُ أنا خلقناه أوّلَ مرةٍ ولم يكن شيئًا موجودًا؟ فالذي أوجده من العدمِ أقدرُ على إعادته؛ ففي هذا حجّةٌ عقليةٌ قاطعةٌ على البعثِ بالخلقِ الأول؛ فتذكّر أصلك من العدمِ ليثبت لك البعث، فإعادةُ الخلقِ أهونُ من ابتدائه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاستدلالُ على البعثِ بالخلقِ الأول."},"action":{"text":"تذكّر أنك كنت عدمًا فأوجدك الله، فمن قدر على خلقك من لا شيءٍ قادرٌ على إعادتك بعد الموت؛ فاستحضر هذه الحجّةَ كلّما وسوس لك شكٌّ في البعث، فتثبت على اليقين."}},{"n":68,"reflection":{"text":"«فوربك لنحشرنهم والشياطين ثم لنحضرنهم حول جهنم جثيا» — فأقسم ربّك لنجمعنّ هؤلاء المنكرين مع الشياطينِ الذين أضلّوهم، ثم لنُحضِرنّهم حولَ جهنمَ جاثين على ركبهم من الهولِ والذلّ؛ ففي هذا أنّ قرناءَ السوءِ يُحشَرون مع من أضلّوهم، وهولُ ذلك الموقف؛ فاحذر قرناءَ السوءِ من الإنسِ والشياطين، فإنهم رفقاؤك في الموقفِ والمصير.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من قرناءِ السوءِ خشيةَ مصيرهم."},"action":{"text":"احذر مصاحبةَ قرناءِ السوءِ من الإنسِ ومتابعةَ الشياطين، فإنّ من صاحبته في الضلالِ تُحشَر معه؛ فاختر قرينك في الدنيا على قدرِ ما ترضى أن تُحشَر معه غدًا."}},{"n":69,"reflection":{"text":"«ثم لننزعن من كل شيعة أيهم أشد على الرحمن عتيا» — ثم لنُخرِجنّ من كلِّ طائفةٍ وفرقةٍ أشدَّهم تمرّدًا وعتوًّا على الرحمنِ فنبدأ بهم في العذاب؛ ففي هذا أنّ العذابَ يشتدّ على قدرِ العتوِّ والتمرّد، وأنّ رؤوسَ الضلالِ أوّلُ من يُعذَّب؛ فاحذر التمادي في العتوِّ على الله، فكلّما زاد التمرّدُ زاد العذاب.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من التمادي في العصيانِ والعتوّ."},"action":{"text":"احذر أن تتمادى في معصيةِ الله والتمرّدِ على أمره، فالعذابُ يشتدّ بقدرِ العتوّ، ورؤوسُ الطغيانِ أوّلُ من يُنزَع للعذاب؛ فكلّما دعتك نفسك للعصيانِ فاذكر هذا."}},{"n":70,"reflection":{"text":"«ثم لنحن أعلم بالذين هم أولى بها صليا» — ثم لنحن أعلمُ بالذين هم أحقُّ بدخولِ النارِ ومقاساةِ حرّها من غيرهم؛ ففي هذا كمالُ علمِ الله وعدلِه في وضعِ العذابِ بأهله، وأنّ الجزاءَ بعلمٍ لا بجزاف؛ فاعمل على ألّا تكون ممّن هم أولى بالنار، وثق بعدلِ الله في جزائه.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الطمأنينةُ إلى عدلِ الله وعلمِه في الجزاء."},"action":{"text":"اعمل جاهدًا ألّا تكون ممّن يستحقون النارَ ويُقدَّمون إليها، وثق بأنّ الله أعلمُ وأعدلُ في وضعِ عذابه بأهله؛ فاحرص على أعمالٍ تباعدك عنها لا تقرّبك منها."}},{"n":71,"reflection":{"text":"«وإن منكم إلا واردها كان على ربك حتما مقضيا» — وما منكم أحدٌ إلا سيرِدُ النارَ (يمرُّ على الصراطِ المنصوبِ عليها)، كان ذلك أمرًا محتومًا مقضيًّا قضاه الله لا بدَّ منه؛ ففي هذا التخويفُ من هولِ المرورِ على الصراط، وأنه واقعٌ بالجميع؛ فاستعدَّ لهذا الورودِ بالتقوى والعمل، فمن اتّقى نجا ومن ظلم هوى.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاستعدادُ لهولِ الورودِ على النارِ بالتقوى."},"action":{"text":"استحضر أنك وارِدٌ على النارِ مارٌّ على الصراطِ لا محالة، فاستعدَّ لذلك الموقفِ بالتقوى والأعمالِ الصالحةِ التي تثبّتك على الصراط؛ فالنجاةُ منها بالعملِ لا بالتمنّي."}},{"n":72,"reflection":{"text":"«ثم ننجي الذين اتقوا ونذر الظالمين فيها جثيا» — ثم ننجّي من الصراطِ الذين اتّقوا الله، ونترك الظالمين في النارِ جاثين على ركبهم؛ ففي هذا أنّ التقوى سببُ النجاةِ يومَ الورود، وأنّ الظلمَ سببُ البقاءِ في العذاب؛ فالزم التقوى فهي سببُ نجاتك، واجتنب الظلمَ فهو سببُ هلاكك.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"لزومُ التقوى سببًا للنجاة، واجتنابُ الظلم."},"action":{"text":"الزم تقوى الله فهي سببُ نجاتك من النارِ يومَ يمرُّ الخلقُ على الصراط، واجتنب الظلمَ بأنواعه فهو سببُ البقاءِ في العذاب؛ فالتقوى منجاةٌ والظلمُ مهلكة."}}]},{"title":"اغترارُ الكفارِ بالدنيا، وزيادةُ المهتدين هدًى","range":[73,76],"theme":"مفاخرةُ الكفارِ بالدنيا، والردُّ بإهلاكِ من قبلهم، وثمرةُ الهدى","verses":[{"n":73,"reflection":{"text":"«وإذا تتلى عليهم آياتنا بينات قال الذين كفروا للذين آمنوا أي الفريقين خير مقاما وأحسن نديا» — وإذا تُقرأ عليهم آياتنا واضحاتٍ قال الكفارُ للمؤمنين مفتخرين: أيُّ الفريقين خيرٌ منزلًا وأحسنُ مجلسًا ومجتمعًا؟ يعنون أنفسهم؛ ففي هذا اغترارُ الكفارِ بسعةِ دنياهم واستدلالُهم بها على رضا الله، وهو باطل؛ فلا تغترَّ بسعةِ الدنيا ولا تجعلها دليلَ الحقّ، فالعبرةُ بالإيمانِ لا بالمتاع.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"عدمُ الاغترارِ بالدنيا وجعلِها دليلَ الحقّ."},"action":{"text":"لا تغترَّ بسعةِ الدنيا لأهلها ولا تظنّها دليلَ رضا الله عنهم، ولا يهزّك تفاخرُ أهلِ الباطلِ بمتاعهم؛ فميزانُ الخيريّةِ الإيمانُ والتقوى لا المالُ والجاه."}},{"n":74,"reflection":{"text":"«وكم أهلكنا قبلهم من قرن هم أحسن أثاثا ورئيا» — وكثيرٌ من الأممِ أهلكناهم قبل هؤلاء، كانوا أكثرَ أموالًا ومتاعًا وأحسنَ منظرًا وهيئة، فلم يغنِ عنهم ذلك شيئًا؛ ففي هذا أنّ متاعَ الدنيا لا يدفع عذابَ الله، وأنّ الاعتبارَ بمصارعِ الأممِ المترفة؛ فاعتبر بمن أهلكهم الله مع غناهم، ولا تظنّ الدنيا مانعةً من بأسِ الله.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاعتبارُ بمصارعِ الأممِ المترفةِ قبلنا."},"action":{"text":"اعتبر بالأممِ التي كانت أكثرَ منك مالًا وأبهى منظرًا فأهلكها الله بكفرها، ولم يغنِ عنها متاعُها؛ فلا تركن إلى الدنيا، واعلم أنها لا تدفع عن أهلها عذابَ الله."}},{"n":75,"reflection":{"text":"«قل من كان في الضلالة فليمدد له الرحمن مدا حتى إذا رأوا ما يوعدون إما العذاب وإما الساعة فسيعلمون من هو شر مكانا وأضعف جندا» — قل: من كان في الضلالِ فسنةُ الله أن يمهله الرحمنُ ويمدّ له في دنياه استدراجًا، حتى إذا رأوا ما وُعِدوا من العذابِ في الدنيا أو قيامِ الساعة، علموا حينئذٍ من هو شرُّ منزلةً وأضعفُ أنصارًا؛ ففي هذا أنّ الإمهالَ استدراجٌ لا إكرام، وأنّ الحقيقةَ تنكشف عند العذاب؛ فلا يغرّنك إمهالُ الله لأهلِ الضلال، فالعاقبةُ تكشف الحقّ.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"عدمُ الاغترارِ بالإمهال، واليقينُ بانكشافِ العاقبة."},"action":{"text":"لا يغرّنك إمهالُ الله لأهلِ الضلالِ وطولُ متاعهم، فإنما هو استدراج؛ واعلم أنّ الحقيقةَ تنكشف عند العذابِ وقيامِ الساعة، فيتبيّن من هو شرُّ مكانًا وأضعفُ جندًا."}},{"n":76,"reflection":{"text":"«ويزيد الله الذين اهتدوا هدى والباقيات الصالحات خير عند ربك ثوابا وخير مردا» — ويزيد الله المهتدين هدًى بتوفيقهم للطاعةِ وثباتهم عليها، والأعمالُ الصالحاتُ الباقيةُ خيرٌ عند ربّك ثوابًا وخيرٌ عاقبةً ومرجعًا؛ ففي هذا أنّ الهدى يزيد بالعمل، وأنّ الباقياتِ الصالحاتِ خيرٌ من متاعِ الكفارِ الزائل؛ فاعمل الصالحاتِ يزدك الله هدى، وقدّم الباقياتِ على الفانيات.","source":"تفسير السعدي","grade":"ma'thur"},"names":["والباقيات الصالحات"],"heart_state":{"text":"العملُ لزيادةِ الهدى، وتقديمُ الباقياتِ الصالحات."},"action":{"text":"اعمل بما تعلم من الهدى يزدك الله هدًى وتوفيقًا، وأكثر من الباقياتِ الصالحاتِ (الذكرِ والصلاةِ والصدقة)، فهي خيرٌ عند الله ثوابًا وعاقبةً من كلِّ متاعٍ زائل."}}]},{"title":"المغترُّ بالمالِ والولد، وبطلانُ عبادةِ الأنداد","range":[77,82],"theme":"من زعم أنه يُؤتى مالًا وولدًا في الآخرة، وتبرّؤُ الآلهةِ من عابديها","verses":[{"n":77,"reflection":{"text":"«أفرأيت الذي كفر بآياتنا وقال لأوتين مالا وولدا» — أفرأيت يا محمد عجبًا من الذي كفر بآياتنا وزعم أنه سيُعطى في الآخرةِ مالًا وولدًا (كما أُعطي في الدنيا)؟ ففي هذا اغترارُ الكافرِ بما أُوتي في الدنيا وقياسُه الآخرةَ عليها، وهو باطل؛ فلا تقس أمرَ الآخرةِ على الدنيا، ولا تظنّ أنّ عطاءَ الدنيا دليلٌ على عطاءِ الآخرةِ لمن كفر.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"عدمُ قياسِ الآخرةِ على الدنيا في العطاء."},"action":{"text":"لا تظنّ أنّ من وُسِّع عليه في الدنيا سيُعطى مثلَه في الآخرة، فالعطاءان مختلفان؛ فمتاعُ الدنيا قد يكون استدراجًا، وعطاءُ الآخرةِ بالإيمانِ والعملِ لا بالكفر."}},{"n":78,"reflection":{"text":"«أطلع الغيب أم اتخذ عند الرحمن عهدا» — هل اطّلع هذا القائلُ على الغيبِ فعلم أنه يُعطى، أم اتّخذ عند الرحمنِ عهدًا بذلك؟ لا هذا ولا ذاك؛ ففي هذا إبطالُ دعواه بأنها بلا علمٍ ولا عهد، وأنّ القولَ على الله بلا علمٍ باطل؛ فلا تقل على الله ما لا تعلم، ولا تدّعِ لنفسك عند الله ما ليس لك.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"تركُ القولِ على الله بلا علم، ونبذُ الدعاوى الباطلة."},"action":{"text":"لا تقل على الله ما لا علمَ لك به، ولا تدّعِ لنفسك عند الله منزلةً أو عطاءً بلا برهان؛ فدعوى الجزمِ بالغيبِ أو العهدِ عند الله بلا دليلٍ افتراءٌ وكذب، فتحرَّ الصدق."}},{"n":79,"reflection":{"text":"«كلا سنكتب ما يقول ونمد له من العذاب مدا» — ليس الأمرُ كما زعم، سنكتب ما يقوله من الكفرِ والدعوى ونزيده من العذابِ زيادةً على زيادة؛ ففي هذا أنّ الأقوالَ تُكتَب ويُحاسَب عليها، وأنّ الافتراءَ على الله يزيد العذاب؛ فراقب لسانك فيما تقول، فكلُّ قولٍ محفوظٌ محاسَبٌ عليه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"مراقبةُ اللسانِ فكلُّ قولٍ مكتوبٌ محاسَبٌ عليه."},"action":{"text":"راقب ما ينطق به لسانك، فكلُّ كلمةٍ تُكتَب وتُحاسَب عليها، وافتراءُ الكذبِ على الله يزيد العذاب؛ فاحفظ لسانك عن كلِّ باطلٍ وكذبٍ ودعوى لا برهانَ عليها."}},{"n":80,"reflection":{"text":"«ونرثه ما يقول ويأتينا فردا» — ونرثُ ما عنده من المالِ والولدِ الذي افتخر به بعد موته، ويأتينا يوم القيامةِ فردًا لا مالَ معه ولا ولد؛ ففي هذا أنّ ما يُفاخِر به المرءُ يزول ويأتي ربّه وحيدًا مجرَّدًا، وأنّ العبرةَ بما قدّم لا بما جمع؛ فلا تعتمد على مالٍ أو ولدٍ يفارقك، وقدّم لنفسك ما تلقى الله به.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"العلمُ بأنّ المرءَ يأتي ربّه فردًا مجرَّدًا."},"action":{"text":"لا تعتمد على مالٍ أو ولدٍ أو جاهٍ فكلُّه يفارقك، وستأتي ربّك فردًا كما خلقك؛ فقدّم لنفسك من العملِ الصالحِ ما تلقى الله به، فهو وحده الذي يبقى لك ويصحبك."}},{"n":81,"reflection":{"text":"«واتخذوا من دون الله آلهة ليكونوا لهم عزا» — واتّخذ المشركون من دون الله آلهةً يعبدونها ليكونوا لهم عزًّا وأنصارًا ينصرونهم؛ ففي هذا بيانُ باعثِ الشركِ الفاسدِ: طلبُ العزّ من غيرِ الله، وهو موجبُ الذلّ؛ فاطلب العزَّ من الله وحده، فمن ابتغى العزَّ بغيرِ الله أذلّه الله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["ليكونوا لهم عزا"],"heart_state":{"text":"طلبُ العزِّ من الله وحده لا من سواه."},"action":{"text":"اطلب العزَّ والنصرَ من الله وحده، ولا تتعلّق بغيره رجاءَ عزٍّ أو قوّة؛ فمن طلب العزَّ من مخلوقٍ أو معبودٍ باطلٍ أورثه الله ذلًّا، والعزُّ كلُّه بيدِ الله."}},{"n":82,"reflection":{"text":"«كلا سيكفرون بعبادتهم ويكونون عليهم ضدا» — ليس الأمرُ كما ظنّوا، بل ستجحد تلك الآلهةُ عبادتهم لها وتتبرّأ منهم، وتكون عليهم أعداءً وخصماءَ يوم القيامة؛ ففي هذا أنّ ما عُبِد من دون الله يتبرّأ من عابديه، وأنّ من طلب العزَّ بالباطلِ ناله الذلّ؛ فلا تعبد ما يخذلك ويتبرّأ منك، وأخلص العبادةَ لله الذي لا يتخلّى عن عبده.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"إخلاصُ العبادةِ لله، والحذرُ من التعلّقِ بمن يتبرّأ."},"action":{"text":"أخلص عبادتك لله وحده، ولا تتعلّق بمعبودٍ أو مخلوقٍ سيتبرّأ منك ويكون خصمًا لك يوم القيامة؛ فالله وحده لا يخذل من عبده ولا يتخلّى عمّن أخلص له."}}]},{"title":"تسليطُ الشياطينِ، ومشهدُ الوفدِ والورد","range":[83,87],"theme":"إزعاجُ الشياطينِ للكافرين، وحشرُ المتّقين وفدًا والمجرمين وردًا","verses":[{"n":83,"reflection":{"text":"«ألم تر أنا أرسلنا الشياطين على الكافرين تؤزهم أزا» — ألم تعلم أنا سلّطنا الشياطينَ على الكافرين تزعجهم إلى المعاصي إزعاجًا وتحرّكهم إليها تحريكًا؟ ففي هذا أنّ الكافرَ يُوكَل إلى شيطانه فيقوده إلى الشرّ، وأنّ الإعراضَ عن الله يسلّط الشيطان؛ فاعتصم بالله وذكرِه من الشيطان، فبالغفلةِ يتسلّط وبالذكرِ يندحر.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاعتصامُ بذكرِ الله من تسلّطِ الشيطان."},"action":{"text":"اعتصم بالله وأكثر من ذكره واستعذ به من الشيطان، فإنّ الغفلةَ عن الله تسلّط الشياطينَ على القلبِ تؤزّه إلى المعاصي؛ فحصّن نفسك بالأذكارِ والطاعةِ يندحر عنك."}},{"n":84,"reflection":{"text":"«فلا تعجل عليهم إنما نعد لهم عدا» — فلا تستعجل يا محمد بطلبِ هلاكهم أو نزولِ العذابِ بهم، إنما نُحصي أنفاسهم وأعمالهم وآجالهم عدًّا دقيقًا حتى يبلغوا الأجلَ المقدّر؛ ففي هذا أنّ لكلِّ شيءٍ أجلًا عند الله، وأنّ الأناةَ أولى من العجلة؛ فلا تستعجل عاقبةَ الظالمين، واصبر فإنّ الله يمهل ولا يهمل، وكلُّ أنفاسهم محصاة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الأناةُ وتركُ العجلةِ في استبطاءِ نصرِ الله."},"action":{"text":"لا تستعجل هلاكَ المخالفين أو نصرَ الله، واصبر فإنّ الله يعدُّ أنفاسهم وآجالهم عدًّا؛ فما تأخّر إلا لحكمة، والعجلةُ من ضعفِ اليقين، والأناةُ من الإيمانِ بتدبيرِ الله."}},{"n":85,"reflection":{"text":"«يوم نحشر المتقين إلى الرحمن وفدا» — اذكر يومَ نجمع المتّقين إلى ربّهم وفدًا مكرَمين راكبين كما يُكرَم الوفدُ عند الملوك؛ ففي هذا بشارةُ المتّقين بحشرٍ كريمٍ يوم القيامة، وأنّ التقوى تورث الكرامةَ عند الله؛ فالزم التقوى تُحشَر في وفدِ الله المكرَمين، لا في زمرةِ المطرودين.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["نحشر المتقين إلى الرحمن وفدا"],"heart_state":{"text":"الرغبةُ في التقوى التي تورث الكرامةَ يومَ الحشر."},"action":{"text":"الزم تقوى الله ليجعلك من وفده المكرَمين يوم القيامةِ يُساقون إلى الجنةِ إكرامًا؛ فتصوّر نفسك في ذلك الوفدِ المكرَمِ ليحملك ذلك على التقوى وترْكِ ما يزري بك."}},{"n":86,"reflection":{"text":"«ونسوق المجرمين إلى جهنم وردا» — ونسوق المجرمين إلى جهنمَ عطاشًا مشاةً يُساقون سوقَ البهائمِ إلى الماءِ في ذلٍّ وهوان؛ ففي هذا مقابلةُ إكرامِ المتّقين بإهانةِ المجرمين، وأنّ الجرمَ يورث الذلَّ يوم القيامة؛ فاحذر الإجرامَ الذي يورث هذا المصيرَ المهين، وقابِل بين المشهدين لتختار.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من الإجرامِ المورثِ للذلِّ يومَ القيامة."},"action":{"text":"احذر المعاصيَ والإجرامَ الذي يُساق صاحبه إلى النارِ ذليلًا عطشانًا، وقابِل بين مشهدِ الوفدِ المكرَمِ ومشهدِ المساقين للنار؛ فليحملك ذلك على التقوى وتركِ الجرم."}},{"n":87,"reflection":{"text":"«لا يملكون الشفاعة إلا من اتخذ عند الرحمن عهدا» — لا يملك الخلقُ أن يشفعوا أو يُشفَع لهم إلا من اتّخذ عند الرحمنِ عهدًا بالإيمانِ والعملِ الصالح (فأذن الله بالشفاعةِ له)؛ ففي هذا أنّ الشفاعةَ لا تُنال إلا بعهدِ الإيمانِ والتوحيد، وأنها بإذنِ الله؛ فاتّخذ عند الله عهدًا بالإيمانِ والطاعةِ لتنالك الشفاعة، فلا شفاعةَ لمن مات على الكفر.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["اتخذ عند الرحمن عهدا"],"heart_state":{"text":"اتّخاذُ العهدِ عند الله بالإيمانِ لنيلِ الشفاعة."},"action":{"text":"اتّخذ عند الله عهدًا بالتوحيدِ والإيمانِ والعملِ الصالحِ والمحافظةِ على العباداتِ والأذكار، فبه تُرجى الشفاعةُ يوم القيامة؛ فوثّق صلتك بالله في دنياك تنفعك غدًا."}}]},{"title":"تنزيهُ الرحمنِ عن الولدِ، وعبوديةُ الخلقِ كلِّهم","range":[88,95],"theme":"عِظَمُ فِريةِ الولد، وأنّ كلَّ من في السماواتِ والأرضِ عبدٌ لله","verses":[{"n":88,"reflection":{"text":"«وقالوا اتخذ الرحمن ولدا» — وقال المشركون واليهودُ والنصارى مفترين: اتّخذ الرحمنُ ولدًا؛ ففي هذا حكايةُ أعظمِ فريةٍ افتُرِيت على الله، تمهيدًا لبيانِ شناعتها؛ فاحذر أن تنسب إلى الله ما لا يليق به، ونزّهه عن كلِّ نقصٍ نسبه إليه الجاهلون.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"تنزيهُ الله عمّا نسبه إليه الجاهلون."},"action":{"text":"نزّه الله عن كلِّ ما لا يليق به ممّا نسبه إليه أهلُ الباطلِ من الولدِ والشريك، واحذر أن تنسب إليه نقصًا أو تصفه بغيرِ ما وصف به نفسه؛ فالتنزيهُ حقُّ الله على عبده."}},{"n":89,"reflection":{"text":"«لقد جئتم شيئا إدا» — لقد قلتم بهذه المقالةِ شيئًا عظيمًا منكرًا بالغَ الشناعة؛ ففي هذا تفظيعُ نسبةِ الولدِ إلى الله، وأنه من أعظمِ المنكرات؛ فعظّم اللهَ في قلبك، واستشعر شناعةَ ما يُقال في حقّه من الباطل، وابرأ منه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"استشعارُ شناعةِ الافتراءِ على الله."},"action":{"text":"استعظم ما يُنسَب إلى الله من الباطلِ كنسبةِ الولدِ إليه، وابرأ منه في قلبك ولسانك؛ فتعظيمُ الله يقتضي استفظاعَ كلِّ ما يُقال في حقّه ممّا لا يليق بجلاله."}},{"n":90,"reflection":{"text":"«تكاد السماوات يتفطرن منه وتنشق الأرض وتخر الجبال هدا» — تكاد السماواتُ تتشقّق والأرضُ تنفطر والجبالُ تسقط منهدّةً من عظمِ هذه الكلمة؛ ففي هذا تصويرُ عظمِ جرمِ نسبةِ الولدِ إلى الله حتى تكاد المخلوقاتُ العظامُ تنهار غضبًا لله؛ فإذا كانت الجماداتُ تكاد تنهار لعظمِ الفرية، فأحرى بقلبك أن يمتلئ غيرةً لله وتعظيمًا له.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الغيرةُ لله وتعظيمُه عند سماعِ الباطلِ في حقّه."},"action":{"text":"املأ قلبك غيرةً لله وتعظيمًا له، فإذا كادت السماواتُ تتفطّر والجبالُ تنهدُّ من كلمةِ الكفرِ في حقّه، فأحرى بك أن تغضب لله وتنكر ما يُقال في جلاله من الباطل."}},{"n":91,"reflection":{"text":"«أن دعوا للرحمن ولدا» — إنما كاد ذلك أن يقع لأجلِ أن نسبوا للرحمنِ ولدًا؛ ففي هذا بيانُ سببِ ذلك الهولِ العظيم، وأنّ التوحيدَ حقُّ الله الذي تغضب المخلوقاتُ لانتهاكه؛ فأخلص التوحيدَ لله، واعلم أنّ أعظمَ الذنوبِ ما مسّ جنابَ التوحيد.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"إجلالُ حقِّ التوحيدِ والغضبُ لانتهاكه."},"action":{"text":"أجلَّ حقَّ الله في توحيده، واعلم أنّ أعظمَ ما يُنتهَك حرمةً حقُّ الله وحده؛ فأخلص له العبادةَ وابرأ من كلِّ ما يخدش التوحيدَ من قولٍ أو اعتقاد."}},{"n":92,"reflection":{"text":"«وما ينبغي للرحمن أن يتخذ ولدا» — وما يليق ولا يصحُّ للرحمنِ سبحانه أن يتّخذ ولدًا، لأنّ الولدَ يقتضي الحاجةَ والمماثلةَ والله غنيٌّ عن كلِّ شيء؛ ففي هذا إثباتُ تنزّهِ الله عن الولدِ بالدليلِ العقليِّ (الغنى المطلق)؛ فاعرف ربّك بالغنى المطلقِ والكمالِ التامّ، ونزّهه عن كلِّ ما يناقض ذلك.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"معرفةُ الله بالغنى المطلقِ وتنزيهُه عن الحاجة."},"action":{"text":"اعرف ربّك بأنه الغنيُّ عن كلِّ شيء، المتّصفُ بكلِّ كمال؛ فمن كان هذا شأنه لا يحتاج إلى ولدٍ ولا شريك؛ فنزّهه عن كلِّ نقصٍ يقتضي الحاجةَ أو المماثلة."}},{"n":93,"reflection":{"text":"«إن كل من في السماوات والأرض إلا آتي الرحمن عبدا» — ما من أحدٍ في السماواتِ والأرضِ من ملَكٍ أو إنسٍ أو جنٍّ إلا سيأتي ربّه يوم القيامةِ عبدًا خاضعًا ذليلًا مقرًّا بالعبودية؛ ففي هذا أنّ الخلقَ كلَّهم عبيدٌ لله (فكيف يكون بعضهم ولدًا له؟)، وأنّ العبوديةَ تعمُّ الجميع؛ فأقرَّ بعبوديّتك لله طوعًا في الدنيا قبل أن تُقِرَّ بها كرهًا يوم القيامة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["آتي الرحمن عبدا"],"heart_state":{"text":"الإقرارُ بالعبوديةِ لله طوعًا في الدنيا."},"action":{"text":"أقرَّ بعبوديّتك لله وأنت طائعٌ مختارٌ في الدنيا، والزم مقتضاها من الطاعةِ والذلِّ له؛ فكلُّ الخلقِ سيأتونه عبيدًا يوم القيامة، فكن ممّن عبده طوعًا لا كرهًا."}},{"n":94,"reflection":{"text":"«لقد أحصاهم وعدهم عدا» — لقد أحاط الله علمًا بجميعِ خلقه وأحصى عددهم إحصاءً دقيقًا لا يفوته منهم أحد؛ ففي هذا كمالُ علمِ الله وإحاطتِه بخلقه، وأنه لا يخفى عليه منهم شيء؛ فاستحضر أنّ الله يعلمك ويحصيك، فاستحيِ أن يراك حيث نهاك، وأنِس بعلمه بك.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"استحضارُ إحاطةِ علمِ الله بالخلق."},"action":{"text":"استحضر أنّ الله أحصى خلقه عددًا ويعلم حالك في كلِّ لحظة، فلا تخفى عليه؛ فاستحيِ منه أن يجدك حيث نهاك، وأنِس بأنّ من أحصاك لا يضيّعك ولا ينساك."}},{"n":95,"reflection":{"text":"«وكلهم آتيه يوم القيامة فردا» — وكلُّ واحدٍ منهم سيأتي ربّه يوم القيامةِ منفردًا لا مالَ معه ولا ولدَ ولا ناصر؛ ففي هذا أنّ العبدَ يلقى ربّه وحيدًا مجرَّدًا إلا من عمله، وأنّ الأنسابَ والأموالَ تنقطع؛ فاعمل لنفسك عملًا يصحبك في وحدتك، ولا تتّكل على ما يفارقك عند لقاءِ الله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاستعدادُ للقاءِ الله فردًا بالعملِ الصالح."},"action":{"text":"أعِدَّ لنفسك عملًا صالحًا يصحبك يوم تلقى الله فردًا وحيدًا، فلا مالَ ولا ولدَ ولا صاحب؛ فلا تعتمد على ما يفارقك، بل على ما قدّمته لآخرتك من صالحِ العمل."}}]},{"title":"وُدُّ المؤمنين، وتيسيرُ القرآن، وعبرةُ القرونِ الخالية","range":[96,98],"theme":"جعلُ الله المودّةَ للمؤمنين، وتيسيرُ القرآنِ للبشرى والنذارة","verses":[{"n":96,"reflection":{"text":"«إن الذين آمنوا وعملوا الصالحات سيجعل لهم الرحمن ودا» — إنّ الذين جمعوا الإيمانَ والعملَ الصالحَ سيجعل الرحمنُ لهم محبّةً في قلوبِ عباده ووُدًّا يُلقيه لهم في الأرض؛ ففي هذا أنّ ثمرةَ الإيمانِ والعملِ محبّةُ الله ومحبّةُ خلقِه، وأنّ القبولَ في الأرضِ من الله؛ فأخلص الإيمانَ والعمل، واطلب الوُدَّ من الله لا بالتكلّفِ والرياء، فالمحبوبُ من أحبّه الله.","source":"تفسير السعدي","grade":"ma'thur"},"names":["سيجعل لهم الرحمن ودا"],"heart_state":{"text":"طلبُ محبّةِ الله ووُدِّه بالإيمانِ والعملِ الصالح."},"action":{"text":"أخلص إيمانك وعملك الصالحَ لله، واطلب منه أن يجعل لك وُدًّا في قلوبِ عباده؛ فالمحبّةُ الصادقةُ تُلتمَس من الله لا بالتصنّعِ للناس، فمن أحبّه الله حبّبه إلى خلقه."}},{"n":97,"reflection":{"text":"«فإنما يسرناه بلسانك لتبشر به المتقين وتنذر به قوما لدا» — فإنما يسّرنا هذا القرآنَ بلغتك العربيةِ لتبشّر به المتّقين بالجنةِ وتنذر به قومًا شِدادَ الخصومةِ بالباطل؛ ففي هذا امتنانُ الله بتيسيرِ القرآن، وأنّ وظيفتَه البشارةُ والنذارة؛ فاجعل القرآنَ ميسَّرًا في قلبك ولسانك تبشيرًا وإنذارًا، وابشّر به وأنذر، فهو ميسَّرٌ للذكر.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["يسرناه بلسانك"],"heart_state":{"text":"شكرُ تيسيرِ القرآن، والانتفاعُ به بشارةً ونذارة."},"action":{"text":"اشكر نعمةَ تيسيرِ القرآنِ بلغتك، واقرأه متدبّرًا تبشيرًا لنفسك بالجنةِ وإنذارًا لها من النار؛ وبلّغه غيرك بشيرًا ونذيرًا، فقد يسّره الله لتُنتفَع به لا ليُهجَر."}},{"n":98,"reflection":{"text":"«وكم أهلكنا قبلهم من قرن هل تحس منهم من أحد أو تسمع لهم ركزا» — وكثيرٌ من الأممِ أهلكناهم قبل هؤلاء المكذّبين، فهل تحسُّ منهم أحدًا باقيًا أو تسمع لهم صوتًا خفيًّا؟ لا شيء، بادوا كأن لم يكونوا؛ ففي هذا خاتمةٌ في الاعتبارِ بفناءِ المكذّبين، وأنّ الدنيا لا تبقي أحدًا؛ فاعتبر بمن مضى، واعمل لآخرتك قبل أن تصير مثلهم أثرًا بعد عين، فما بقيَ إلا وجهُ الله.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاعتبارُ بفناءِ الأممِ والعملُ قبلَ الفوات."},"action":{"text":"اعتبر بالأممِ التي أهلكها الله فلم يبقَ منها أحدٌ ولا صوت، واعلم أنّ الدنيا لا تُبقي أحدًا؛ فبادر بالعملِ لآخرتك قبل أن تصير أثرًا منسيًّا، فالباقي وجهُ الله وما قُدِّم له."}}]}],"coverage":{"covered":98,"total":98}};
